/// Converts the exact Prompting-v2 provider output into Protocol's durable
/// accepted-output mirror without projecting away any field.
///
/// The conversion deliberately crosses through the shared serialized wire and
/// then proves a typed round-trip in both directions. That makes additions,
/// enum drift, invalid UUIDs/digests, and any nested patch or decision-basis
/// mismatch fail closed instead of being silently defaulted.
///
/// # Errors
///
/// Returns [`StoreError::InvalidStateEvent`] when the two typed wires are not
/// isomorphic or when the bound u32 call ceiling is not exactly authorized by
/// the supplied u64 reservation and total/per-call budget.
pub fn protocol_planner_v2_accepted_output(
    output: &PlannerReplannerV2Output,
    reservation: &TokenReservation,
    budget: ModelOutputBudgetV1,
) -> Result<PlannerPromptV2AcceptedOutputV1, StoreError> {
    validate_planner_v2_output_budget(
        &output.bindings.budget_reservation_id,
        output.bindings.max_output_tokens,
        reservation,
        budget,
    )?;
    let source = serde_json::to_value(output)?;
    let protocol = serde_json::from_value::<PlannerPromptV2AcceptedOutputV1>(source.clone())
        .map_err(|_| StoreError::InvalidStateEvent)?;
    let protocol_wire = serde_json::to_value(&protocol)?;
    if protocol_wire != source {
        return Err(StoreError::InvalidStateEvent);
    }
    let restored = serde_json::from_value::<PlannerReplannerV2Output>(protocol_wire)
        .map_err(|_| StoreError::InvalidStateEvent)?;
    if &restored != output {
        return Err(StoreError::InvalidStateEvent);
    }
    Ok(protocol)
}

/// Converts Protocol's durable accepted-output mirror back to the exact
/// Prompting-v2 provider DTO and proves the inverse typed round-trip.
///
/// # Errors
///
/// Returns [`StoreError::InvalidStateEvent`] for any field, enum, digest,
/// identity, or budget mismatch.
pub fn prompting_planner_v2_accepted_output(
    output: &PlannerPromptV2AcceptedOutputV1,
    reservation: &TokenReservation,
    budget: ModelOutputBudgetV1,
) -> Result<PlannerReplannerV2Output, StoreError> {
    validate_planner_v2_output_budget(
        &output.bindings.budget_reservation_id.to_string(),
        output.bindings.max_output_tokens,
        reservation,
        budget,
    )?;
    let source = serde_json::to_value(output)?;
    let prompting = serde_json::from_value::<PlannerReplannerV2Output>(source.clone())
        .map_err(|_| StoreError::InvalidStateEvent)?;
    let prompting_wire = serde_json::to_value(&prompting)?;
    if prompting_wire != source {
        return Err(StoreError::InvalidStateEvent);
    }
    let restored = serde_json::from_value::<PlannerPromptV2AcceptedOutputV1>(prompting_wire)
        .map_err(|_| StoreError::InvalidStateEvent)?;
    if &restored != output {
        return Err(StoreError::InvalidStateEvent);
    }
    Ok(prompting)
}

fn validate_planner_v2_output_budget(
    reservation_id: &str,
    max_output_tokens: u32,
    reservation: &TokenReservation,
    budget: ModelOutputBudgetV1,
) -> Result<(), StoreError> {
    let max_output_tokens = u64::from(max_output_tokens);
    if reservation_id != reservation.id.to_string()
        || max_output_tokens == 0
        || budget.max_total_reserved_output_tokens == 0
        || budget.max_output_tokens_per_call == 0
        || budget.max_output_tokens_per_call > budget.max_total_reserved_output_tokens
        || max_output_tokens > budget.max_output_tokens_per_call
        || reservation.max_output_tokens != max_output_tokens
        || reservation.max_output_tokens > reservation.reserved_tokens
    {
        return Err(StoreError::InvalidStateEvent);
    }
    Ok(())
}

/// Result of an append whose commit is fenced by an absolute wall deadline.
///
/// [`Self::DeadlineElapsed`] means the event passed the same transactional
/// validation as a normal append, but the transaction was explicitly rolled
/// back because the deadline had elapsed before commit.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum DeadlineAppendOutcome {
    Appended,
    DeadlineElapsed,
}

/// A bounded, deterministic page of materialized nonterminal runs.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RunRecoveryPage {
    pub runs: Vec<Run>,
    /// Exclusive run-id cursor for the next page.
    pub next_run_id: Option<RunId>,
    pub has_more: bool,
}

const fn new_run_acceptance_contract_is_valid(run: &Run) -> bool {
    matches!(
        (run.spec.purpose, run.spec.plan_acceptance),
        (
            RunPurpose::PlanOnly | RunPurpose::ParallelRepositoryReconnaissanceV1,
            PlanAcceptanceContract::IndependentSemanticReviewV1
        ) | (RunPurpose::Execute, PlanAcceptanceContract::NotApplicable)
    )
}

const fn supports_root_planning(purpose: RunPurpose) -> bool {
    matches!(
        purpose,
        RunPurpose::PlanOnly | RunPurpose::ParallelRepositoryReconnaissanceV1
    )
}

#[derive(Debug, Error)]
pub enum StoreError {
    #[error("database operation failed: {0}")]
    Database(#[from] rusqlite::Error),
    #[error("stored JSON could not be encoded or decoded: {0}")]
    Json(#[from] serde_json::Error),
    #[error("artifact operation failed: {0}")]
    Io(#[from] io::Error),
    #[error("artifact reference contains an invalid SHA-256 digest")]
    InvalidArtifactHash,
    #[error("artifact is too large to represent in the canonical protocol")]
    ArtifactTooLarge,
    #[error("event exceeds the aggregate artifact reference or byte budget")]
    ArtifactReferenceBudget,
    #[error("artifact content does not match its content-addressed reference")]
    ArtifactIntegrity,
    #[error("event sequence overflowed")]
    SequenceOverflow,
    #[error("inline event exceeds the durable event size limit; store large data as an artifact")]
    EventTooLarge,
    #[error("materialized state and authoritative event disagree")]
    InvalidStateEvent,
    #[error("caller-allocated event identity is already bound to different event fields")]
    IdentifiedEventConflict,
    #[error(
        "database schema version {found} is incompatible with supported version {supported}: {reason}"
    )]
    IncompatibleSchema {
        found: i64,
        supported: i64,
        reason: String,
    },
}

impl StoreError {
    /// Reports a transactional uniqueness or integrity conflict. Callers must
    /// re-read authoritative state before deciding whether an operation was
    /// an idempotent replay or a genuinely conflicting request.
    #[must_use]
    pub fn is_conflict(&self) -> bool {
        match self {
            Self::IdentifiedEventConflict => true,
            Self::Database(rusqlite::Error::SqliteFailure(error, _)) => {
                error.code == rusqlite::ErrorCode::ConstraintViolation
            }
            _ => false,
        }
    }

    /// Reports whether retrying the same operation can plausibly succeed
    /// without changing the database or input.
    #[must_use]
    pub fn is_retryable(&self) -> bool {
        match self {
            Self::Database(rusqlite::Error::SqliteFailure(error, _)) => matches!(
                error.code,
                rusqlite::ErrorCode::DatabaseBusy | rusqlite::ErrorCode::DatabaseLocked
            ),
            Self::Io(error) => matches!(
                error.kind(),
                io::ErrorKind::Interrupted | io::ErrorKind::WouldBlock | io::ErrorKind::TimedOut
            ),
            _ => false,
        }
    }
}

pub struct Store {
    connection: Connection,
    artifact_root: PathBuf,
    last_durable_health_probe: Cell<Option<Instant>>,
}

impl Store {
    fn artifact_path(&self, hash: &str) -> Result<PathBuf, StoreError> {
        artifact_path_at(&self.artifact_root, hash)
    }
}

fn put_artifact_at(
    artifact_root: &Path,
    bytes: &[u8],
    media_type: String,
) -> Result<ArtifactRef, StoreError> {
    let size_bytes = u64::try_from(bytes.len()).map_err(|_| StoreError::ArtifactTooLarge)?;
    if size_bytes > MAX_ARTIFACT_BYTES {
        return Err(StoreError::ArtifactTooLarge);
    }
    let hash = sha256_hex(bytes);
    let path = artifact_path_at(artifact_root, &hash)?;
    let parent = path.parent().ok_or(StoreError::InvalidArtifactHash)?;
    prepare_private_directory(parent)?;
    if !path.exists() {
        let mut temporary = NamedTempFile::new_in(parent)?;
        temporary.write_all(bytes)?;
        temporary.as_file_mut().sync_all()?;
        match temporary.persist_noclobber(&path) {
            Ok(_) => {
                sync_directory(parent)?;
                if parent != artifact_root {
                    sync_directory(artifact_root)?;
                }
            }
            Err(error) if error.error.kind() == io::ErrorKind::AlreadyExists => {}
            Err(error) => return Err(StoreError::Io(error.error)),
        }
    }
    set_private_file_permissions(&path)?;
    let artifact = ArtifactRef {
        sha256: hash,
        size_bytes,
        media_type,
    };
    read_verified_artifact(&path, &artifact)?;
    Ok(artifact)
}
fn incompatible(found: i64, reason: impl Into<String>) -> StoreError {
    StoreError::IncompatibleSchema {
        found,
        supported: CURRENT_SCHEMA_VERSION,
        reason: reason.into(),
    }
}

const MAX_CHILD_REPLAY_EVENTS: u32 = 1
    + PARALLEL_RECONNAISSANCE_V1_MAX_CLAIM_ADOPTIONS_PER_CHILD
    + CHILD_RECONNAISSANCE_MAX_ATTEMPTS
        * (3 + 2 * CHILD_RECONNAISSANCE_MAX_MODEL_CALLS_PER_ATTEMPT
            + 2 * CHILD_RECONNAISSANCE_MAX_TOOL_CALLS_PER_ATTEMPT);

