    #[allow(
        clippy::too_many_lines,
        reason = "the closed cleanup grant deliberately carries its complete typed safety evidence"
    )]
    pub(crate) fn generic_cleanup_v2_payloads(
        store: &Store,
        session_id: SessionId,
    ) -> [EventPayload; 4] {
        let run_id = RunId::new();
        let cleanup_grant_event_id = EventId::new();
        let cleanup_grant_id = RepositorySnapshotCleanupGrantId::new();
        let recovery_id = RepositorySnapshotRecoveryId::new();
        let local_cleanup_id = RepositorySnapshotLocalCleanupId::new();
        let lease_id = RepositorySnapshotLeaseId::new();
        let snapshot_lease_event_id = EventId::new();
        let writer_revocation_event_id = EventId::new();
        let cleanup_actor_id = ActorId::new();
        let cleanup_runtime_instance_id = RuntimeInstanceId::new();
        let evidence_artifact = fixture_artifact(store, "generic-cleanup-v2-rejection");
        let evidence_digest = Sha256Digest::parse(evidence_artifact.sha256.clone())
            .expect("fixture artifact hash should be a canonical digest");
        let snapshot_id = "snapshot-generic-cleanup-v2-rejection".to_owned();
        let paths = RepositorySnapshotRecoveryPathsV1 {
            source_path: PathBuf::from("/repo").into(),
            image_path: PathBuf::from("/state/images/rejected.dmg").into(),
            mount_path: PathBuf::from("/state/mounts/rejected").into(),
        };
        let clock = |monotonic_nanos| RuntimeClockReading {
            runtime_instance_id: cleanup_runtime_instance_id,
            monotonic_nanos,
            observed_at: Utc::now(),
        };
        let cleanup_scope = RepositorySnapshotCleanupEffectScopeV2 {
            session_id,
            run_id,
            cleanup_grant_event_id,
            cleanup_grant_id,
            cleanup_grant_generation: 1,
            recovery_id,
            local_cleanup_id,
            snapshot_id: snapshot_id.clone(),
            lease_id,
            snapshot_lease_event_id,
            writer_revocation_event_id,
            paths: paths.clone(),
        };
        let topology_inspection = RepositorySnapshotRetainedCleanupInitialTopologyInspectionV2 {
            inspection_artifact: evidence_artifact.clone(),
            inspection_digest: evidence_digest.clone(),
            inspection: RepositorySnapshotCleanupInitialTopologyInspectionDocumentV2 {
                schema_version: 2,
                scope: cleanup_scope,
                phase: RepositorySnapshotCleanupInitialInspectionPhaseV2::PreGrantInitial,
                operation: RepositorySnapshotCleanupInspectOperationV2::InspectDiskImageTopology,
                executable: PathBuf::from("/usr/bin/hdiutil").into(),
                exit_code: 0,
                stdout_artifact: evidence_artifact.clone(),
                stdout_digest: evidence_digest.clone(),
                stderr_artifact: evidence_artifact.clone(),
                stderr_digest: evidence_digest.clone(),
                topology:
                    RepositorySnapshotRecoveryTopologyObservationV1::NoExpectedImageOrMountAttached,
                image: RepositorySnapshotRecoveryImageObservationV1::Missing,
                mount: RepositorySnapshotRecoveryMountObservationV1::Missing,
                completed_at: clock(2),
            },
        };
        let process_quiescence = RepositorySnapshotRetainedCleanupProcessInspectionV1 {
            inspection_artifact: evidence_artifact.clone(),
            inspection_digest: evidence_digest.clone(),
            inspection: RepositorySnapshotCleanupProcessInspectionDocumentV1 {
                schema_version: 1,
                session_id,
                run_id,
                cleanup_grant_event_id,
                cleanup_grant_id,
                cleanup_grant_generation: 1,
                recovery_id,
                local_cleanup_id,
                snapshot_id: snapshot_id.clone(),
                lease_id,
                snapshot_lease_event_id,
                mount_path: paths.mount_path.clone(),
                guardian_actor_id: cleanup_actor_id,
                guardian_runtime_instance_id: cleanup_runtime_instance_id,
                process_registry_generation: 1,
                effect_fence_generation: 1,
                effect_fence: RepositorySnapshotCleanupEffectFenceObservationV1::ArmedRejectingNewMountReadersAndSnapshotEffects,
                inspected_processes:
                    RepositorySnapshotCleanupProcessInspectionSetV1::try_from_vec(Vec::new())
                        .expect("an empty exact process set is bounded"),
                mount_readers: RepositorySnapshotCleanupMountReaderObservationV1::NoGuardianOwnedProcessReferencesMount,
                snapshot_effects: RepositorySnapshotCleanupEffectObservationV1::NoGuardianOwnedSnapshotEffectInFlight,
                observed_at: clock(1),
            },
        };
        let initial_inspection = RepositorySnapshotRetainedCleanupInitialInspectionV1 {
            inspection_artifact: evidence_artifact.clone(),
            inspection_digest: evidence_digest.clone(),
            inspection: RepositorySnapshotCleanupInitialInspectionDocumentV1 {
                schema_version: 1,
                session_id,
                run_id,
                cleanup_grant_event_id,
                cleanup_grant_id,
                cleanup_grant_generation: 1,
                recovery_id,
                local_cleanup_id,
                snapshot_id: snapshot_id.clone(),
                lease_id,
                snapshot_lease_event_id,
                writer_revocation_event_id,
                paths,
                topology:
                    RepositorySnapshotRecoveryTopologyObservationV1::NoExpectedImageOrMountAttached,
                image: RepositorySnapshotRecoveryImageObservationV1::Missing,
                mount: RepositorySnapshotRecoveryMountObservationV1::Missing,
                topology_inspection,
                observed_at: clock(3),
            },
        };
        let safety_evidence = RepositorySnapshotRetainedCleanupSafetyEvidenceV1 {
            evidence_artifact: evidence_artifact.clone(),
            evidence_digest: evidence_digest.clone(),
            evidence: RepositorySnapshotCleanupSafetyEvidenceDocumentV1 {
                schema_version: 1,
                session_id,
                run_id,
                cleanup_grant_event_id,
                cleanup_grant_id,
                cleanup_grant_generation: 1,
                recovery_id,
                local_cleanup_id,
                snapshot_id: snapshot_id.clone(),
                lease_id,
                snapshot_lease_event_id,
                writer_revocation_event_id,
                process_quiescence,
                initial_inspection,
                observed_at: clock(4),
            },
        };
        let closure_event_id = EventId::new();
        let workspace_finalized_event_id = EventId::new();
        let grant = RepositorySnapshotCleanupGrantedV1 {
            schema_version: 1,
            session_id,
            run_id,
            cleanup_grant_event_id,
            cleanup_grant_id,
            cleanup_grant_generation: 1,
            recovery_id,
            local_cleanup_id,
            closure_event_id,
            workspace_finalized_event_id,
            kind: RepositorySnapshotCleanupKindV1::CaptureAbandonment,
            boundary: RepositorySnapshotCleanupBoundaryV1::PriorClaimExpired {
                claim_lease_expires_at: Utc::now(),
            },
            lifecycle_tail_event_id: writer_revocation_event_id,
            snapshot_id,
            lease_id,
            snapshot_lease_event_id,
            writer_revocation_event_id,
            lifecycle_owner_actor_id: ActorId::new(),
            lifecycle_owner_runtime_instance_id: RuntimeInstanceId::new(),
            source_claim_event_id: EventId::new(),
            source_claim_id: RunClaimId::new(),
            source_claim_generation: 1,
            source_claim_actor_id: ActorId::new(),
            source_claim_runtime_instance_id: RuntimeInstanceId::new(),
            cancellation_generation: 0,
            cleanup_actor_id,
            cleanup_runtime_instance_id,
            safety_evidence,
            granted_at: clock(5),
            grant_expires_at: Utc::now(),
        };
        let abandonment = RepositorySnapshotCaptureAbandonedV2 {
            schema_version: 2,
            recovery_id,
            cleanup_grant_event_id,
            cleanup_grant_id,
            cleanup_grant_generation: 1,
            workspace_finalized_event_id,
            writer_revocation_event_id,
            snapshot_lease_event_id,
            lease_id,
            recovery_artifact: evidence_artifact.clone(),
            recovery_digest: evidence_digest.clone(),
        };
        let reconciliation = RepositorySnapshotReleaseReconciledV2 {
            schema_version: 2,
            recovery_id,
            cleanup_grant_event_id,
            cleanup_grant_id,
            cleanup_grant_generation: 1,
            workspace_finalized_event_id,
            writer_revocation_event_id,
            snapshot_lease_event_id,
            lease_id,
            recovery_artifact: evidence_artifact.clone(),
            recovery_digest: evidence_digest.clone(),
        };
        let finalized = WorkspaceRecoveryFinalizedV1 {
            schema_version: 1,
            finalization_id: WorkspaceRecoveryFinalizationId::new(),
            recovery_id,
            cleanup_grant_event_id,
            cleanup_grant_id,
            cleanup_grant_generation: 1,
            closure_event_id,
            recovery_artifact: evidence_artifact.clone(),
            recovery_digest: evidence_digest.clone(),
            finalization_artifact: evidence_artifact,
            finalization_digest: evidence_digest,
        };
        [
            EventPayload::RepositorySnapshotCleanupGrantedV1(grant),
            EventPayload::RepositorySnapshotCaptureAbandonedV2(abandonment),
            EventPayload::RepositorySnapshotReleaseReconciledV2(reconciliation),
            EventPayload::WorkspaceRecoveryFinalizedV1(finalized),
        ]
    }

    fn durable_event_row_counts(store: &Store) -> (u64, u64) {
        let durable_rows = store
            .connection
            .query_row("SELECT COUNT(*) FROM events", [], |row| {
                row.get::<_, u64>(0)
            })
            .expect("durable event count should load");
        let identity_rows = store
            .connection
            .query_row(
                "SELECT COUNT(*) FROM event_identity_projection",
                [],
                |row| row.get::<_, u64>(0),
            )
            .expect("event identity count should load");
        (durable_rows, identity_rows)
    }

    #[test]
    fn public_generic_append_paths_reject_all_cleanup_v2_events_without_persistence() {
        let (_directory, mut store, session_event) = store_with_session_event();
        let payloads = generic_cleanup_v2_payloads(&store, session_event.session_id);
        let baseline = store
            .events_after(session_event.session_id, 0)
            .expect("session history should load")
            .events;

        for payload in payloads {
            let result = store.append_event(NewEvent {
                session_id: session_event.session_id,
                run_id: None,
                actor_id: ActorId::new(),
                causal_parent: Some(session_event.id),
                provenance: provenance(),
                payload: payload.clone(),
            });
            assert!(matches!(result, Err(StoreError::InvalidStateEvent)));
            assert!(matches!(
                store.append_event_before_deadline(
                    NewEvent {
                        session_id: session_event.session_id,
                        run_id: None,
                        actor_id: ActorId::new(),
                        causal_parent: Some(session_event.id),
                        provenance: provenance(),
                        payload,
                    },
                    Utc::now() + chrono::Duration::minutes(1),
                ),
                Err(StoreError::InvalidStateEvent)
            ));
            assert_eq!(
                store
                    .events_after(session_event.session_id, 0)
                    .expect("rejected append must leave readable history")
                    .events,
                baseline,
                "generic cleanup append must not persist an event"
            );
            assert_eq!(durable_event_row_counts(&store), (1, 1));
        }
    }

    #[test]
    fn cleanup_handoff_is_pointer_sized_and_exposes_only_borrowed_full_envelopes() {
        let (_directory, _store, envelope) = store_with_session_event();
        let cleanup_grant_event = envelope.clone();
        let writer_revocation_event = envelope.clone();
        let latest_capture_event = envelope;
        let handoff = RepositorySnapshotCleanupHandoffV1 {
            kind: Box::new(RepositorySnapshotCleanupHandoffKindV1::CaptureAbandonment {
                cleanup_grant_event: cleanup_grant_event.clone(),
                writer_revocation_event: writer_revocation_event.clone(),
                latest_capture_event: latest_capture_event.clone(),
            }),
        };

        assert_eq!(
            std::mem::size_of_val(&handoff),
            std::mem::size_of::<usize>()
        );
        let RepositorySnapshotCleanupHandoffViewV1::CaptureAbandonment {
            cleanup_grant_event: viewed_grant,
            writer_revocation_event: viewed_writer,
            latest_capture_event: viewed_capture,
        } = handoff.view()
        else {
            panic!("capture cleanup handoff must preserve its closed target")
        };
        assert_eq!(viewed_grant, &cleanup_grant_event);
        assert_eq!(viewed_writer, &writer_revocation_event);
        assert_eq!(viewed_capture, &latest_capture_event);
    }

    #[test]
    fn cleanup_handoff_lease_view_preserves_every_borrowed_target_envelope() {
        let (_directory, _store, envelope) = store_with_session_event();
        let cleanup_grant_event = envelope.clone();
        let writer_revocation_event = envelope.clone();
        let lease_event = envelope;
        let handoff = RepositorySnapshotCleanupHandoffV1 {
            kind: Box::new(
                RepositorySnapshotCleanupHandoffKindV1::LeaseReleaseReconciliation {
                    cleanup_grant_event: cleanup_grant_event.clone(),
                    writer_revocation_event: writer_revocation_event.clone(),
                    lease_event: lease_event.clone(),
                },
            ),
        };

        let RepositorySnapshotCleanupHandoffViewV1::LeaseReleaseReconciliation {
            cleanup_grant_event: viewed_grant,
            writer_revocation_event: viewed_writer,
            lease_event: viewed_lease,
        } = handoff.view()
        else {
            panic!("lease cleanup handoff must preserve its closed target")
        };
        assert_eq!(viewed_grant, &cleanup_grant_event);
        assert_eq!(viewed_writer, &writer_revocation_event);
        assert_eq!(viewed_lease, &lease_event);
    }

    #[test]
    fn pending_cleanup_capture_replay_projects_exact_target_and_refresh_status() {
        let mut fixture = child_v6_contract_tests::parallel_recon_claim_refresh_fixture(0);
        child_v6_contract_tests::open_snapshot_capture_for_refresh(&mut fixture);
        let replay = replay_repository_snapshot_lifecycle(
            &fixture.store.connection,
            &fixture.store.artifact_root,
            &fixture.run,
        )
        .expect("open capture fixture replays");
        let RepositorySnapshotLifecycleReplay::Open(open) = replay else {
            panic!("fixture must retain an open capture")
        };
        let writer_revocation_event = open.writer_revocation_event.clone();
        let latest_capture_event = open.latest_capture_event.clone();
        let EventPayload::RepositorySnapshotCleanupGrantedV1(grant) =
            generic_cleanup_v2_payloads(&fixture.store, fixture.run.spec.session_id)
                .into_iter()
                .next()
                .expect("cleanup fixture contains its grant first")
        else {
            panic!("cleanup fixture grant is typed")
        };
        let mut cleanup_grant_event = latest_capture_event.clone();
        cleanup_grant_event.id = EventId::new();
        cleanup_grant_event.payload =
            EventPayload::RepositorySnapshotCleanupGrantedV1(grant.clone());
        let pending = RepositorySnapshotLifecycleReplay::PendingCleanup {
            target: RepositorySnapshotCleanupTargetReplay::Capture { open },
            grants: vec![RepositorySnapshotCleanupGrantReplay {
                event: cleanup_grant_event.clone(),
                grant: grant.clone(),
            }],
        };

        assert!(matches!(
            pending.projection(),
            RepositorySnapshotLifecycleProjection::PendingCleanup {
                writer_revocation_event: projected_writer,
                target:
                    RepositorySnapshotCleanupTargetProjectionV1::CaptureAbandonment {
                        latest_capture_event: projected_capture,
                    },
                latest_cleanup_grant_event: projected_grant,
                grant_count: 1,
            } if projected_writer == writer_revocation_event
                && projected_capture == latest_capture_event
                && projected_grant == cleanup_grant_event
        ));
        assert_eq!(
            pending.refresh_status(),
            ParallelReconSnapshotRefreshStatus::CleanupInProgress {
                cleanup_grant_event_id: cleanup_grant_event.id,
                kind: RepositorySnapshotCleanupKindV1::CaptureAbandonment,
                cleanup_grant_generation: grant.cleanup_grant_generation,
            }
        );
    }

