    #[test]
    fn pending_cleanup_payload_fence_blocks_authority_but_not_observations() {
        let mut fixture = child_v6_contract_tests::parallel_recon_claim_refresh_fixture(1);
        let open = child_v6_contract_tests::open_snapshot_capture_for_refresh(&mut fixture);
        let events = fixture
            .store
            .events_for_run_after(fixture.run.id, 0)
            .expect("fixture history reads")
            .events;
        let claim = events
            .iter()
            .find(|event| matches!(event.payload, EventPayload::RunClaimed(_)))
            .expect("fixture has a claim")
            .payload
            .clone();
        let child = events
            .iter()
            .find(|event| matches!(event.payload, EventPayload::ChildWorkOrderIssued(_)))
            .expect("fixture has child authority")
            .payload
            .clone();
        let cleanup = generic_cleanup_v2_payloads(&fixture.store, fixture.run.spec.session_id)
            .into_iter()
            .next()
            .expect("cleanup fixture contains its grant first");
        let blocked = vec![
            ("claim", claim),
            ("child", child),
            ("snapshot", open.writer_event.payload),
            ("cleanup", cleanup),
            (
                "completed",
                EventPayload::RunStateChanged {
                    from: RunState::Running,
                    to: RunState::Completed,
                },
            ),
            (
                "failed",
                EventPayload::RunStateChanged {
                    from: RunState::Running,
                    to: RunState::Failed,
                },
            ),
            (
                "cancelled",
                EventPayload::RunStateChanged {
                    from: RunState::Running,
                    to: RunState::Cancelled,
                },
            ),
        ]
        .into_boxed_slice();
        for (label, payload) in blocked {
            assert!(
                pending_cleanup_blocks_payload(&payload),
                "pending cleanup must block {label} authority"
            );
        }

        let observation_artifact = fixture_artifact(&fixture.store, "cleanup-observation");
        let allowed = [
            EventPayload::UserInput { items: Vec::new() },
            EventPayload::ArtifactStored {
                artifact: observation_artifact,
            },
            EventPayload::BackendEvent {
                event_type: "cleanup_observation".to_owned(),
                data: serde_json::json!({"status": "observed"}),
            },
            EventPayload::CancellationRequested(CancellationRequested {
                cancellation_request_id: birdcode_protocol::CancellationRequestId::new(),
                cancellation_generation: 1,
            }),
            EventPayload::RunStateChanged {
                from: RunState::Running,
                to: RunState::Waiting,
            },
        ];
        for payload in allowed {
            assert!(
                !pending_cleanup_blocks_payload(&payload),
                "observation/cancellation paths must remain outside the cleanup authority fence"
            );
        }
    }

