    #[test]
    fn identified_generic_append_rejects_preexisting_cleanup_v2_events_before_idempotency() {
        let (_directory, mut store, session_event) = store_with_session_event();
        let payloads = generic_cleanup_v2_payloads(&store, session_event.session_id);

        for payload in payloads {
            let event_id = EventId::new();
            let transaction = store
                .connection
                .transaction_with_behavior(TransactionBehavior::Immediate)
                .expect("fixture transaction begins");
            let envelope = preallocate_identified_event_envelope(
                &transaction,
                event_id,
                NewEvent {
                    session_id: session_event.session_id,
                    run_id: None,
                    actor_id: ActorId::new(),
                    causal_parent: Some(session_event.id),
                    provenance: provenance(),
                    payload,
                },
            )
            .expect("reserved fixture event preallocates");
            insert_event_in_transaction(&transaction, &envelope)
                .expect("fixture simulates future Store-owned persistence");
            transaction.commit().expect("fixture event commits");
            let before = durable_event_row_counts(&store);

            let result = store.append_identified_event(IdentifiedNewEvent {
                event_id,
                event: new_event_from_envelope(&envelope),
            });
            assert!(matches!(result, Err(StoreError::InvalidStateEvent)));
            assert_eq!(
                durable_event_row_counts(&store),
                before,
                "public idempotency must not accept or mutate a Store-owned cleanup event"
            );
        }
    }

