        pub(super) fn insert_fixture_event(store: &mut Store, event: NewEvent) -> EventEnvelope {
            let transaction = store
                .connection
                .transaction_with_behavior(TransactionBehavior::Immediate)
                .expect("fixture transaction begins");
            let envelope = preallocate_event_envelope(&transaction, event)
                .expect("fixture event envelope preallocates");
            insert_event_in_transaction(&transaction, &envelope)
                .expect("fixture event inserts without semantic admission");
            transaction.commit().expect("fixture event commits");
            envelope
        }

        #[allow(
            clippy::too_many_lines,
            reason = "the fixture creates complete durable authority for every Store-derived child adoption"
        )]
        pub(super) fn parallel_recon_claim_refresh_fixture(
            child_count: u32,
        ) -> ParallelReconClaimRefreshFixture {
            parallel_recon_claim_refresh_fixture_with_lease(
                child_count,
                chrono::Duration::minutes(10),
            )
        }

        fn parallel_recon_claim_refresh_fixture_with_lease(
            child_count: u32,
            claim_lease_duration: chrono::Duration,
        ) -> ParallelReconClaimRefreshFixture {
            parallel_recon_claim_refresh_fixture_with_limit(
                child_count,
                child_count.max(1),
                claim_lease_duration,
            )
        }

        #[allow(
            clippy::too_many_lines,
            reason = "the fixture constructs a complete multi-child durable refresh history"
        )]
        fn parallel_recon_claim_refresh_fixture_with_limit(
            child_count: u32,
            max_subagents: u32,
            claim_lease_duration: chrono::Duration,
        ) -> ParallelReconClaimRefreshFixture {
            let directory = TempDir::new().expect("temporary directory should be created");
            let database_path = directory.path().join("state.sqlite3");
            let artifact_root = directory.path().join("artifacts");
            let mut store =
                Store::open(&database_path, &artifact_root).expect("refresh fixture store opens");
            let actor_id = ActorId::new();
            let runtime_instance_id = RuntimeInstanceId::new();
            let session = Session::new(CreateSessionRequest {
                workspace_root: PathBuf::from("/tmp/parallel-recon-claim-refresh").into(),
                title: Some("parallel recon claim refresh".to_owned()),
            });
            let session_created = store
                .create_session(&session, session_event(&session, actor_id))
                .expect("session persists");
            let (backend, resolved_model, model_lineage) = backend();
            let run = Run::new(birdcode_protocol::RunSpec {
                session_id: session.id,
                purpose: RunPurpose::ParallelRepositoryReconnaissanceV1,
                plan_acceptance: PlanAcceptanceContract::IndependentSemanticReviewV1,
                backend: backend.clone(),
                input: vec![InputItem::Text {
                    text: "Inspect through every issued child".to_owned(),
                }],
                limits: birdcode_protocol::RunLimits {
                    max_output_tokens: Some(65_536),
                    max_wall_time_seconds: Some(600),
                    max_subagents,
                },
            });
            let run_created = store
                .create_run(
                    &run,
                    NewEvent {
                        session_id: session.id,
                        run_id: Some(run.id),
                        actor_id,
                        causal_parent: Some(session_created.id),
                        provenance: provenance(),
                        payload: EventPayload::RunCreated { run: run.clone() },
                    },
                )
                .expect("run persists");
            let initial_claim_id = RunClaimId::new();
            let initial_claim_event = store
                .append_event(NewEvent {
                    session_id: session.id,
                    run_id: Some(run.id),
                    actor_id,
                    causal_parent: Some(run_created.id),
                    provenance: provenance(),
                    payload: EventPayload::RunClaimed(RunClaimed {
                        claim_id: initial_claim_id,
                        runtime_instance_id,
                        claim_generation: 1,
                        cancellation_generation: 0,
                        lease_expires_at: Utc::now() + claim_lease_duration,
                    }),
                })
                .expect("initial claim persists");
            let EventPayload::RunClaimed(initial_claim) = initial_claim_event.payload.clone()
            else {
                panic!("fixture claim is typed")
            };
            let running = store
                .append_event(NewEvent {
                    session_id: session.id,
                    run_id: Some(run.id),
                    actor_id,
                    causal_parent: Some(initial_claim_event.id),
                    provenance: provenance(),
                    payload: EventPayload::RunStateChanged {
                        from: RunState::Queued,
                        to: RunState::Running,
                    },
                })
                .expect("run starts");

            let mut work_order_ids = Vec::new();
            for ordinal in 0..child_count {
                let repository_authority = authority(&store);
                let spec = ChildWorkOrderSpec {
                    contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                    work_order_id: ChildWorkOrderId::new(),
                    execution_id: ChildExecutionId::new(),
                    child_actor_id: birdcode_protocol::ChildActorId::new(),
                    child_event_actor_id: ActorId::new(),
                    context_id: birdcode_protocol::ChildContextId::new(),
                    role: ChildReconnaissanceRole::ReadOnlyRepositoryExplorer,
                    backend: backend.clone(),
                    resolved_model: resolved_model.clone(),
                    backend_instance: Some(test_protocol_backend_instance(
                        "lmstudio-local",
                        "local-m4",
                    )),
                    model_lineage: model_lineage.clone(),
                    planner_work_order_local_id: format!("refresh-child-{ordinal}"),
                    objective: format!("Inspect exact repository evidence partition {ordinal}"),
                    completion_contract: "Return an evidence-bound handoff".to_owned(),
                    run_deadline: None,
                    repository_authority,
                    max_attempts: 2,
                    min_plan_revisions: 2,
                    max_model_calls_per_attempt: 8,
                    max_tool_calls_per_attempt: 8,
                    max_model_evidence_bytes: 256 * 1024,
                    max_model_visible_input_bytes:
                        birdcode_protocol::CHILD_REPOSITORY_EXPLORER_V1_MAX_RAW_INPUT_BYTES as u64,
                };
                let work_order_artifact = put_json(&store, &spec, CHILD_WORK_ORDER_MEDIA_TYPE);
                let work_order_digest = digest_ref(&work_order_artifact);
                let context_manifest = ChildContextManifest {
                    contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                    work_order_id: spec.work_order_id,
                    context_id: spec.context_id,
                    sources: vec![birdcode_protocol::ChildContextSourceV1 {
                        source_event_id: running.id,
                        artifact: None,
                    }],
                };
                let context_manifest_artifact =
                    put_json(&store, &context_manifest, CHILD_CONTEXT_MANIFEST_MEDIA_TYPE);
                let context_manifest_digest = digest_ref(&context_manifest_artifact);
                let accepted_plan_artifact = store
                    .put_artifact(
                        format!("accepted-plan-{ordinal}").as_bytes(),
                        ACCEPTED_PLAN_MEDIA_TYPE,
                    )
                    .expect("accepted-plan fixture persists");
                let authorization = ChildDelegationAuthorized {
                    authorization_id: birdcode_protocol::ChildDelegationAuthorizationId::new(),
                    issuer_actor_id: actor_id,
                    claim_event_id: initial_claim_event.id,
                    claim_id: initial_claim_id,
                    claim_generation: 1,
                    claim_runtime_instance_id: runtime_instance_id,
                    cancellation_generation: 0,
                    accepted_plan_event_id: running.id,
                    accepted_plan_digest: digest_ref(&accepted_plan_artifact),
                    accepted_plan_artifact,
                    snapshot_lease_event_id: running.id,
                    planner_work_order_local_id: spec.planner_work_order_local_id.clone(),
                    spec: spec.clone(),
                    work_order_artifact: work_order_artifact.clone(),
                    work_order_digest: work_order_digest.clone(),
                    context_manifest_artifact: context_manifest_artifact.clone(),
                    context_manifest_digest: context_manifest_digest.clone(),
                };
                let authorization_event = insert_fixture_event(
                    &mut store,
                    NewEvent {
                        session_id: session.id,
                        run_id: Some(run.id),
                        actor_id,
                        causal_parent: Some(running.id),
                        provenance: Provenance {
                            producer: "fixture-refresh-authority".to_owned(),
                            backend: None,
                            raw_artifact: Some(work_order_artifact.clone()),
                        },
                        payload: EventPayload::ChildDelegationAuthorized(authorization),
                    },
                );
                let issued = ChildWorkOrderIssued {
                    issuer_actor_id: actor_id,
                    authorization_event_id: authorization_event.id,
                    authorization_claim_event_id: initial_claim_event.id,
                    authorization_claim_id: initial_claim_id,
                    authorization_claim_generation: 1,
                    authorization_runtime_instance_id: runtime_instance_id,
                    spec: spec.clone(),
                    work_order_artifact: work_order_artifact.clone(),
                    work_order_digest,
                    context_manifest_artifact,
                    context_manifest_digest,
                    cancellation_generation: 0,
                };
                insert_fixture_event(
                    &mut store,
                    NewEvent {
                        session_id: session.id,
                        run_id: Some(run.id),
                        actor_id,
                        causal_parent: Some(authorization_event.id),
                        provenance: Provenance {
                            producer: "fixture-refresh-issuer".to_owned(),
                            backend: None,
                            raw_artifact: Some(work_order_artifact),
                        },
                        payload: EventPayload::ChildWorkOrderIssued(issued),
                    },
                );
                work_order_ids.push(spec.work_order_id);
            }
            ParallelReconClaimRefreshFixture {
                _directory: directory,
                database_path,
                artifact_root,
                store,
                run,
                actor_id,
                runtime_instance_id,
                initial_claim: DurableRunClaimProjection {
                    event: initial_claim_event,
                    claim: initial_claim,
                },
                work_order_ids,
            }
        }

        pub(super) fn parallel_recon_refresh_authority(
            fixture: &ParallelReconClaimRefreshFixture,
        ) -> ParallelReconClaimRefreshAuthority {
            let now = Utc::now();
            ParallelReconClaimRefreshAuthority {
                actor_id: fixture.actor_id,
                runtime_instance_id: fixture.runtime_instance_id,
                renewal_claim_id: RunClaimId::new(),
                snapshot_capture_adoption_id: RepositorySnapshotCaptureClaimAdoptionId::new(),
                child_adoption_ids: [
                    birdcode_protocol::ChildClaimAdoptionId::new(),
                    birdcode_protocol::ChildClaimAdoptionId::new(),
                ],
                refreshed_at: RuntimeClockReading {
                    runtime_instance_id: fixture.runtime_instance_id,
                    monotonic_nanos: 20,
                    observed_at: now,
                },
                fresh_through: now + chrono::Duration::minutes(20),
                renewed_lease_expires_at: now + chrono::Duration::minutes(30),
            }
        }

