        pub(super) fn open_snapshot_capture_for_refresh(
            fixture: &mut ParallelReconClaimRefreshFixture,
        ) -> OpenSnapshotCaptureFixture {
            let snapshot_id = format!("refresh-snapshot-{}", fixture.run.id);
            let lease_id = birdcode_protocol::RepositorySnapshotLeaseId::new();
            let lease_event_id = EventId::new();
            let revoked_at = RuntimeClockReading {
                runtime_instance_id: fixture.runtime_instance_id,
                monotonic_nanos: 10,
                observed_at: Utc::now(),
            };
            let evidence = RepositoryWriterLeaseEvidenceDocumentV1 {
                schema_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                writer_lease_id: format!("refresh-writer-{}", fixture.run.id),
                writer_lease_generation: 1,
                source_path: PathBuf::from("/tmp/parallel-recon-claim-refresh").into(),
                source_root_identity: birdcode_protocol::RepositoryFileIdentityV1::Unix(
                    birdcode_protocol::RepositoryUnixFileIdentityV1 {
                        device: 1,
                        inode: 2,
                        byte_len: 0,
                        modified_seconds: 1,
                        modified_nanoseconds: 0,
                        changed_seconds: 1,
                        changed_nanoseconds: 0,
                    },
                ),
                exclusive: true,
                active_writer_count: 0,
                revoked_at,
            };
            let evidence_artifact = put_json(
                &fixture.store,
                &evidence,
                REPOSITORY_WRITER_LEASE_EVIDENCE_MEDIA_TYPE,
            );
            let evidence_digest = digest_ref(&evidence_artifact);
            let writer_event = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.run.spec.session_id,
                    run_id: Some(fixture.run.id),
                    actor_id: fixture.actor_id,
                    causal_parent: Some(fixture.initial_claim.event.id),
                    provenance: Provenance {
                        producer: "fixture-open-snapshot-capture".to_owned(),
                        backend: None,
                        raw_artifact: Some(evidence_artifact.clone()),
                    },
                    payload: EventPayload::RepositoryWriterLeaseRevoked(
                        RepositoryWriterLeaseRevokedV1 {
                            issuer_actor_id: fixture.actor_id,
                            claim_event_id: fixture.initial_claim.event.id,
                            claim_id: fixture.initial_claim.claim.claim_id,
                            claim_generation: fixture.initial_claim.claim.claim_generation,
                            claim_runtime_instance_id: fixture.runtime_instance_id,
                            cancellation_generation: 0,
                            capture: birdcode_protocol::RepositorySnapshotCaptureIdentityV1 {
                                snapshot_id: snapshot_id.clone(),
                                lease_id,
                                snapshot_lease_event_id: lease_event_id,
                            },
                            evidence_artifact,
                            evidence_digest,
                        },
                    ),
                })
                .expect("open snapshot writer revocation persists");
            OpenSnapshotCaptureFixture {
                writer_event,
                snapshot_id,
                lease_id,
                lease_event_id,
            }
        }

