        fn owned_capture_adoption_handoff(
            outcome: &ParallelReconClaimRefreshOutcome,
        ) -> (EventEnvelope, EventEnvelope, EventEnvelope) {
            let (ParallelReconClaimRefreshOutcome::Fresh {
                snapshot_claim: ParallelReconSnapshotClaimHandoffOutcomeV1::Issued(handoff),
                ..
            }
            | ParallelReconClaimRefreshOutcome::Renewed {
                snapshot_claim: ParallelReconSnapshotClaimHandoffOutcomeV1::Issued(handoff),
                ..
            }) = outcome
            else {
                panic!("refresh must issue snapshot claim authority")
            };
            let ParallelReconSnapshotClaimHandoffViewV1::CaptureAdoption {
                previous_claim,
                current_claim,
                adoption,
            } = handoff.view()
            else {
                panic!("refresh must carry one exact capture adoption")
            };
            (
                previous_claim.clone(),
                current_claim.clone(),
                adoption.clone(),
            )
        }

        fn assert_fresh_open_capture_reissues_exact_adoption(
            outcomes: &[ParallelReconClaimRefreshOutcome],
        ) {
            let renewed = outcomes
                .iter()
                .find(|outcome| matches!(outcome, ParallelReconClaimRefreshOutcome::Renewed { .. }))
                .expect("one refresh renews");
            let fresh = outcomes
                .iter()
                .find(|outcome| matches!(outcome, ParallelReconClaimRefreshOutcome::Fresh { .. }))
                .expect("one refresh re-reads fresh state");
            assert!(matches!(
                fresh,
                ParallelReconClaimRefreshOutcome::Fresh {
                    snapshot:
                        ParallelReconSnapshotRefreshStatus::OpenCapture {
                            active_claim_event_id,
                            ..
                        },
                    claim,
                    ..
                } if *active_claim_event_id == claim.event.id
            ));
            assert_eq!(
                owned_capture_adoption_handoff(fresh),
                owned_capture_adoption_handoff(renewed),
                "Fresh must reissue the exact committed adoption without appending another"
            );
        }

        #[test]
        fn concurrent_same_runtime_refreshes_coalesce_to_one_renewed_and_one_fresh() {
            let mut fixture = parallel_recon_claim_refresh_fixture(2);
            open_snapshot_capture_for_refresh(&mut fixture);
            let left_authority = parallel_recon_refresh_authority(&fixture);
            let right_authority = parallel_recon_refresh_authority(&fixture);
            let database_path = fixture.database_path.clone();
            let artifact_root = fixture.artifact_root.clone();
            let run_id = fixture.run.id;
            drop(fixture.store);
            let left_store =
                Store::open(&database_path, &artifact_root).expect("first concurrent Store opens");
            let right_store =
                Store::open(&database_path, &artifact_root).expect("second concurrent Store opens");
            let barrier = std::sync::Arc::new(std::sync::Barrier::new(2));
            let left_barrier = std::sync::Arc::clone(&barrier);
            let left = std::thread::spawn(move || {
                let mut store = left_store;
                left_barrier.wait();
                store.refresh_parallel_recon_claim(run_id, left_authority)
            });
            let right = std::thread::spawn(move || {
                let mut store = right_store;
                barrier.wait();
                store.refresh_parallel_recon_claim(run_id, right_authority)
            });
            let outcomes = [
                left.join()
                    .expect("left refresh thread joins")
                    .expect("left refresh succeeds"),
                right
                    .join()
                    .expect("right refresh thread joins")
                    .expect("right refresh succeeds"),
            ];
            assert_eq!(
                outcomes
                    .iter()
                    .filter(|outcome| {
                        matches!(outcome, ParallelReconClaimRefreshOutcome::Renewed { .. })
                    })
                    .count(),
                1
            );
            assert_eq!(
                outcomes
                    .iter()
                    .filter(|outcome| {
                        matches!(outcome, ParallelReconClaimRefreshOutcome::Fresh { .. })
                    })
                    .count(),
                1
            );
            assert_fresh_open_capture_reissues_exact_adoption(&outcomes);
            let reopened =
                Store::open(&database_path, &artifact_root).expect("coalesced state reopens");
            let events = reopened
                .events_for_run_after(run_id, 0)
                .expect("coalesced history reads")
                .events;
            assert_eq!(
                events
                    .iter()
                    .filter(|event| matches!(event.payload, EventPayload::RunClaimed(_)))
                    .count(),
                2,
                "initial claim plus exactly one atomic renewal"
            );
            assert_eq!(
                events
                    .iter()
                    .filter(|event| {
                        matches!(event.payload, EventPayload::ChildExecutionClaimAdopted(_))
                    })
                    .count(),
                2
            );
            assert_eq!(
                events
                    .iter()
                    .filter(|event| matches!(
                        event.payload,
                        EventPayload::RepositorySnapshotCaptureClaimAdoptedV1(_)
                    ))
                    .count(),
                1,
                "the coalesced renewal adopts the open capture exactly once"
            );
        }

        #[test]
        fn dropped_capture_adoption_handoff_is_redeemable_in_the_same_process() {
            let mut fixture = parallel_recon_claim_refresh_fixture(0);
            open_snapshot_capture_for_refresh(&mut fixture);
            let renewed = fixture
                .store
                .refresh_parallel_recon_claim(
                    fixture.run.id,
                    parallel_recon_refresh_authority(&fixture),
                )
                .expect("first refresh commits the capture adoption");
            let expected = owned_capture_adoption_handoff(&renewed);
            drop(renewed);

            let fresh = fixture
                .store
                .refresh_parallel_recon_claim(
                    fixture.run.id,
                    parallel_recon_refresh_authority(&fixture),
                )
                .expect("fresh refresh re-reads committed adoption");
            assert!(matches!(
                fresh,
                ParallelReconClaimRefreshOutcome::Fresh { .. }
            ));
            assert_eq!(owned_capture_adoption_handoff(&fresh), expected);
            assert_eq!(
                fixture
                    .store
                    .events_for_run_after(fixture.run.id, 0)
                    .expect("history reads")
                    .events
                    .iter()
                    .filter(|event| matches!(
                        event.payload,
                        EventPayload::RepositorySnapshotCaptureClaimAdoptedV1(_)
                    ))
                    .count(),
                1,
                "re-redemption must not append a second adoption"
            );
        }

