        fn append_total_child_claim_adoption(
            fixture: &mut TotalChildPreparationFixture,
            causal_parent: EventId,
            new_runtime_instance_id: RuntimeInstanceId,
            kind: ChildClaimAdoptionKindV1,
        ) -> (DurableRunClaimProjection, EventEnvelope) {
            let projection = fixture
                .store
                .child_work_order_projection(fixture.run.id, fixture.spec.work_order_id)
                .expect("child replay remains valid before adoption")
                .expect("issued child exists");
            let prior = projection.active_claim;
            let new_actor_id = match kind {
                ChildClaimAdoptionKindV1::Renewal => prior.event.actor_id,
                ChildClaimAdoptionKindV1::Takeover => ActorId::new(),
            };
            let claim = RunClaimed {
                claim_id: RunClaimId::new(),
                runtime_instance_id: new_runtime_instance_id,
                claim_generation: prior.claim.claim_generation + 1,
                cancellation_generation: prior.claim.cancellation_generation,
                lease_expires_at: Utc::now() + chrono::Duration::minutes(10),
            };
            let claim_parent = latest_run_event(
                &fixture.store.connection,
                fixture.run.spec.session_id,
                fixture.run.id,
            )
            .expect("latest run event exists");
            let claim_event = NewEvent {
                session_id: fixture.run.spec.session_id,
                run_id: Some(fixture.run.id),
                actor_id: new_actor_id,
                causal_parent: Some(claim_parent.id),
                provenance: provenance(),
                payload: EventPayload::RunClaimed(claim.clone()),
            };
            let claim_event = match kind {
                ChildClaimAdoptionKindV1::Renewal => fixture
                    .store
                    .append_event(claim_event)
                    .expect("same-runtime claim renewal persists"),
                ChildClaimAdoptionKindV1::Takeover => {
                    // A real takeover is admitted only after the prior wall-clock
                    // lease expires. The fixture inserts that already-admitted
                    // claim directly so the replay test has no timing sleep.
                    insert_fixture_event(&mut fixture.store, claim_event)
                }
            };
            let adoption = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.run.spec.session_id,
                    run_id: Some(fixture.run.id),
                    actor_id: new_actor_id,
                    causal_parent: Some(causal_parent),
                    provenance: Provenance {
                        producer: "fixture-child-claim-adoption".to_owned(),
                        backend: None,
                        raw_artifact: None,
                    },
                    payload: EventPayload::ChildExecutionClaimAdopted(
                        birdcode_protocol::ChildExecutionClaimAdoptedV1 {
                            adoption_id: birdcode_protocol::ChildClaimAdoptionId::new(),
                            work_order_id: fixture.spec.work_order_id,
                            execution_id: fixture.spec.execution_id,
                            attempt_id: Some(fixture.binding.attempt_id),
                            prior_claim_event_id: prior.event.id,
                            prior_claim_id: prior.claim.claim_id,
                            prior_claim_generation: prior.claim.claim_generation,
                            prior_runtime_instance_id: prior.claim.runtime_instance_id,
                            new_claim_event_id: claim_event.id,
                            new_claim_id: claim.claim_id,
                            new_claim_generation: claim.claim_generation,
                            new_runtime_instance_id,
                            cancellation_generation: claim.cancellation_generation,
                            kind,
                        },
                    ),
                })
                .expect("exact child claim adoption persists");
            (
                DurableRunClaimProjection {
                    event: claim_event,
                    claim,
                },
                adoption,
            )
        }

        #[allow(
            clippy::too_many_lines,
            reason = "the fixture retains the exact model-authored action and complete broker-v1 preparation receipt"
        )]
        fn prepare_total_child_tool_from_observed_action(
            fixture: &mut TotalChildPreparationFixture,
            observed_event: &EventEnvelope,
            causal_parent: EventId,
            runtime_instance_id: RuntimeInstanceId,
            monotonic_nanos: u64,
        ) -> EventEnvelope {
            let EventPayload::ChildModelInferenceObserved(observed) = &observed_event.payload
            else {
                panic!("source event is a model observation")
            };
            let retained = read_canonical_json_artifact::<ChildModelEvidenceRecord>(
                &fixture.store.artifact_root,
                &observed.normalized_complete_evidence_artifact,
                CHILD_MODEL_EVIDENCE_MEDIA_TYPE,
            )
            .expect("model evidence remains readable");
            let ChildModelCompleteEvidence::Succeeded {
                normalized_response,
                ..
            } = retained.outcome
            else {
                panic!("source model observation succeeded")
            };
            let plan = normalized_response.plan;
            let action = normalized_response.action;
            let source_plan = ChildLocalPlanBindingV1 {
                plan_id: plan.plan_id,
                revision: plan.revision,
                plan_digest: canonical_digest(&plan).expect("source plan is canonical"),
            };
            let action_document = ChildValidatedActionDocumentV1 {
                contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: fixture.binding.clone(),
                action_id: ChildValidatedActionId::new(),
                source_model_call_id: observed.model_call_id,
                source_model_call_ordinal: observed.model_call_ordinal,
                source_model_observed_event_id: observed_event.id,
                source_model_evidence_digest: observed.evidence_digest.clone(),
                source_plan: source_plan.clone(),
                active_plan_step_id: plan.active_step_id.clone(),
                completion_handoff_id: None,
                action: action.clone(),
            };
            let action_artifact = put_json(
                &fixture.store,
                &action_document,
                CHILD_VALIDATED_ACTION_MEDIA_TYPE,
            );
            let action_binding = ChildValidatedActionBindingV1 {
                action_id: action_document.action_id,
                source_model_call_id: observed.model_call_id,
                source_model_call_ordinal: observed.model_call_ordinal,
                source_model_observed_event_id: observed_event.id,
                source_model_evidence_digest: observed.evidence_digest.clone(),
                source_plan,
                active_plan_step_id: plan.active_step_id,
                completion_handoff_id: None,
                validated_action_digest: digest_ref(&action_artifact),
                validated_action_artifact: action_artifact,
            };
            let tool_grant_id = action
                .tool_grant_id()
                .expect("fixture response selects a repository tool");
            let operation = action
                .tool_operation()
                .expect("fixture response has exact tool parameters");
            let tool_grant = fixture
                .spec
                .repository_authority
                .tool_grants
                .iter()
                .find(|grant| grant.tool_grant_id() == tool_grant_id)
                .expect("selected grant exists")
                .clone();
            let tool_call_id = ChildToolCallId::new();
            let parameters = RepositoryToolCanonicalParametersV1 {
                schema_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: fixture.binding.clone(),
                tool_call_id,
                tool_ordinal: 1,
                action_binding: action_binding.clone(),
                tool_grant_id,
                operation: operation.clone(),
            };
            let parameters_artifact = put_json(
                &fixture.store,
                &parameters,
                REPOSITORY_TOOL_CANONICAL_PARAMETERS_MEDIA_TYPE,
            );
            let broker_instance_id = RepositoryBrokerInstanceId::new();
            let prepared_at = test_clock(runtime_instance_id, monotonic_nanos);
            let receipt = RepositoryToolPreparedReceiptV1 {
                schema_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: fixture.binding.clone(),
                tool_call_id,
                tool_ordinal: 1,
                action_binding: action_binding.clone(),
                operation: operation.clone(),
                authority: RepositoryToolReceiptAuthorityV1 {
                    policy_id: fixture.spec.repository_authority.policy_id.clone(),
                    policy_artifact: fixture.spec.repository_authority.policy_artifact.clone(),
                    policy_digest: fixture.spec.repository_authority.policy_digest.clone(),
                    snapshot: fixture.spec.repository_authority.snapshot.clone(),
                    root: fixture.spec.repository_authority.root.clone(),
                    broker_bounds: fixture.spec.repository_authority.broker_bounds,
                    tool_grant,
                },
                canonical_parameters_digest: digest_ref(&parameters_artifact),
                canonical_parameters_artifact: parameters_artifact,
                authorization: RepositoryToolAuthorizationDecisionV1::Authorized,
                broker_call_sequence: 1,
                broker_prepared_at: RepositoryBrokerClockV1 {
                    broker_instance_id,
                    monotonic_nanos: 100,
                },
                runtime_prepared_at: prepared_at.clone(),
            };
            let receipt_artifact = put_json(
                &fixture.store,
                &receipt,
                REPOSITORY_TOOL_PREPARED_RECEIPT_MEDIA_TYPE,
            );
            fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.run.spec.session_id,
                    run_id: Some(fixture.run.id),
                    actor_id: fixture.spec.child_event_actor_id,
                    causal_parent: Some(causal_parent),
                    provenance: Provenance {
                        producer: "fixture-total-child-tool".to_owned(),
                        backend: Some(fixture.spec.backend.clone()),
                        raw_artifact: Some(receipt_artifact.clone()),
                    },
                    payload: EventPayload::ChildToolPrepared(ChildToolPrepared {
                        binding: fixture.binding.clone(),
                        tool_call_id,
                        tool_ordinal: 1,
                        action_binding,
                        operation,
                        authorization: RepositoryToolAuthorizationDecisionV1::Authorized,
                        broker_instance_id,
                        broker_call_sequence: 1,
                        prepared_receipt_digest: digest_ref(&receipt_artifact),
                        prepared_receipt_artifact: receipt_artifact,
                        prepared_at,
                    }),
                })
                .expect("first tool boundary in the active runtime prepares")
        }

        fn observe_total_child_tree_tool(
            fixture: &mut TotalChildPreparationFixture,
            prepared_event: &EventEnvelope,
            causal_parent: EventId,
            runtime_instance_id: RuntimeInstanceId,
            monotonic_nanos: u64,
        ) -> Result<EventEnvelope, StoreError> {
            let EventPayload::ChildToolPrepared(prepared) = &prepared_event.payload else {
                panic!("fixture tool boundary is Prepared")
            };
            let (replay, _, _, _) = load_child_replay(
                &fixture.store.connection,
                &fixture.store.artifact_root,
                fixture.run.id,
                fixture.spec.work_order_id,
            )
            .expect("pending tool replay validates");
            let pending = replay
                .expect("issued child exists")
                .attempts
                .last()
                .expect("attempt exists")
                .pending_tool
                .clone()
                .expect("tool remains pending");
            assert_eq!(pending.prepared_event_id, prepared_event.id);
            let result = RepositoryToolResultV1::RepositoryTree(RepositoryTreeResultV1 {
                entries: vec![RepositoryTreeEntryV1 {
                    path: RepositoryRelativePathV1::Unix {
                        components: vec![b"src".to_vec()],
                    },
                    kind: birdcode_protocol::RepositoryNodeKindV1::Directory,
                    byte_len: None,
                }],
                directory_entries_scanned: 1,
                directory_name_bytes_scanned: 3,
                truncated: false,
            });
            let (media_type, bytes) =
                encode_repository_tool_result(&result).expect("tree result encodes");
            let inline_result = evidence_artifact(media_type, bytes.clone());
            let result_artifact = fixture
                .store
                .put_artifact(&bytes, media_type)
                .expect("tree result persists");
            assert_eq!(result_artifact, repository_artifact_ref(&inline_result));
            let finished_at = test_clock(runtime_instance_id, monotonic_nanos);
            let receipt = RepositoryToolObservedReceiptV1 {
                schema_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: fixture.binding.clone(),
                tool_call_id: prepared.tool_call_id,
                prepared_event_id: prepared_event.id,
                action_binding: prepared.action_binding.clone(),
                prepared_receipt_digest: prepared.prepared_receipt_digest.clone(),
                operation: prepared.operation.clone(),
                observation: RepositoryToolTerminalObservationV1::Succeeded(result),
                normalized_evidence_artifact: inline_result,
                partial_artifact: None,
                broker_completed_at: RepositoryBrokerClockV1 {
                    broker_instance_id: pending.broker_instance_id,
                    monotonic_nanos: 150,
                },
                elapsed_nanoseconds: 50,
                effect: RepositoryFilesystemEffectV1::ReadOnlyFilesystemAccessAttempted,
                cleanup: RepositoryCleanupReportV1::Completed {
                    disposition:
                        RepositoryCleanupDispositionV1::TransientDescriptorsClosedByOwnershipScope,
                    persistent_resources_created: 0,
                    temporary_resources_created: 0,
                },
                runtime_finished_at: finished_at.clone(),
            };
            let receipt_artifact =
                put_json(&fixture.store, &receipt, CHILD_TOOL_EVIDENCE_MEDIA_TYPE);
            fixture.store.append_event(NewEvent {
                session_id: fixture.run.spec.session_id,
                run_id: Some(fixture.run.id),
                actor_id: fixture.spec.child_event_actor_id,
                causal_parent: Some(causal_parent),
                provenance: Provenance {
                    producer: "fixture-total-child-tool".to_owned(),
                    backend: Some(fixture.spec.backend.clone()),
                    raw_artifact: Some(receipt_artifact.clone()),
                },
                payload: EventPayload::ChildToolObserved(birdcode_protocol::ChildToolObserved {
                    binding: fixture.binding.clone(),
                    tool_call_id: prepared.tool_call_id,
                    prepared_event_id: prepared_event.id,
                    action_binding: prepared.action_binding.clone(),
                    prepared_receipt_digest: prepared.prepared_receipt_digest.clone(),
                    terminal_receipt_digest: digest_ref(&receipt_artifact),
                    terminal_receipt_artifact: receipt_artifact,
                    finished_at,
                    outcome: ChildToolObservation::Succeeded {
                        result: ChildToolSuccess::TreeEnumerated {
                            result_artifact,
                            entries_returned: 1,
                            directory_entries_scanned: 1,
                            directory_name_bytes_scanned: 3,
                            truncated: false,
                        },
                    },
                }),
            })
        }

        fn reconcile_total_child_tool_unknown(
            fixture: &mut TotalChildPreparationFixture,
            prepared_event: &EventEnvelope,
            causal_parent: EventId,
            runtime_instance_id: RuntimeInstanceId,
            monotonic_nanos: u64,
        ) -> Result<EventEnvelope, StoreError> {
            let EventPayload::ChildToolPrepared(prepared) = &prepared_event.payload else {
                panic!("fixture tool boundary is Prepared")
            };
            let (replay, _, _, _) = load_child_replay(
                &fixture.store.connection,
                &fixture.store.artifact_root,
                fixture.run.id,
                fixture.spec.work_order_id,
            )?;
            let pending = replay
                .ok_or(StoreError::InvalidStateEvent)?
                .attempts
                .last()
                .ok_or(StoreError::InvalidStateEvent)?
                .pending_tool
                .clone()
                .ok_or(StoreError::InvalidStateEvent)?;
            let boundary = RepositoryInterruptionBoundaryV1::RuntimeRestart;
            let effect = RepositoryFilesystemEffectV1::Indeterminate;
            let unknown_evidence = RepositoryToolUnknownEvidenceV1 {
                call_id: prepared.tool_call_id,
                boundary,
                effect,
            };
            let unknown_evidence_artifact = evidence_artifact(
                "application/vnd.birdcode.repository-tool-unknown.v1+json",
                serde_json::to_vec(&unknown_evidence)?,
            );
            let boundary_at = test_clock(runtime_instance_id, monotonic_nanos);
            let receipt = RepositoryToolUnknownReceiptV1 {
                schema_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: fixture.binding.clone(),
                tool_call_id: prepared.tool_call_id,
                prepared_event_id: prepared_event.id,
                action_binding: prepared.action_binding.clone(),
                prepared_receipt_digest: prepared.prepared_receipt_digest.clone(),
                operation: prepared.operation.clone(),
                boundary,
                cancellation: None,
                unknown_evidence_artifact,
                partial_artifact: None,
                broker_recorded_at: RepositoryBrokerClockV1 {
                    broker_instance_id: pending.broker_instance_id,
                    monotonic_nanos: 150,
                },
                elapsed_nanoseconds: 50,
                effect,
                cleanup: RepositoryCleanupReportV1::Indeterminate {
                    recovery:
                        birdcode_protocol::RepositoryCleanupRecoveryV1::RuntimeReconciliationRequired,
                    recovery_evidence: None,
                },
                runtime_boundary_at: boundary_at.clone(),
            };
            let receipt_artifact =
                put_json(&fixture.store, &receipt, CHILD_TOOL_UNKNOWN_MEDIA_TYPE);
            fixture.store.append_event(NewEvent {
                session_id: fixture.run.spec.session_id,
                run_id: Some(fixture.run.id),
                actor_id: fixture.spec.child_event_actor_id,
                causal_parent: Some(causal_parent),
                provenance: Provenance {
                    producer: "fixture-total-child-tool".to_owned(),
                    backend: Some(fixture.spec.backend.clone()),
                    raw_artifact: Some(receipt_artifact.clone()),
                },
                payload: EventPayload::ChildToolOutcomeUnknown(ChildToolOutcomeUnknown {
                    binding: fixture.binding.clone(),
                    tool_call_id: prepared.tool_call_id,
                    prepared_event_id: prepared_event.id,
                    action_binding: prepared.action_binding.clone(),
                    prepared_receipt_digest: prepared.prepared_receipt_digest.clone(),
                    terminal_receipt_digest: digest_ref(&receipt_artifact),
                    terminal_receipt_artifact: receipt_artifact,
                    boundary_at,
                    reason: ChildToolUnknownReason::RuntimeRestartedBeforeObservation,
                    boundary: ChildToolUnknownBoundary::Restart,
                    cancellation: None,
                }),
            })
        }

        #[test]
        fn total_child_prepare_is_idempotent_recoverable_and_backend_ready() {
            let mut fixture = total_child_preparation_fixture();
            let first = fixture
                .store
                .prepare_child_repository_explorer_turn(
                    fixture.run.id,
                    fixture.spec.work_order_id,
                    fixture.authority.clone(),
                )
                .expect("total preparation commits and reconstructs");
            assert!(matches!(
                first.append,
                IdempotentAppendOutcome::Appended { .. }
            ));
            assert_eq!(first.material.prepared_event.id, fixture.authority.event_id);
            assert_eq!(first.material.turn_input.binding, fixture.binding);
            assert_eq!(
                serde_json::to_value(&first.material.backend_request).unwrap(),
                serde_json::to_value(&first.material.request.backend_request).unwrap()
            );

            let recovered = fixture
                .store
                .recover_child_repository_explorer_turn(fixture.run.id, fixture.spec.work_order_id)
                .expect("recovery projection validates")
                .expect("pending model request is recoverable");
            assert_eq!(recovered, first.material);
            let retry = fixture
                .store
                .prepare_child_repository_explorer_turn(
                    fixture.run.id,
                    fixture.spec.work_order_id,
                    fixture.authority.clone(),
                )
                .expect("same authority retries idempotently");
            assert!(matches!(
                retry.append,
                IdempotentAppendOutcome::AlreadyPresent { .. }
            ));
            assert_eq!(retry.material, first.material);
        }

        #[test]
        fn total_child_model_observation_normalizes_and_retains_exact_success() {
            let mut fixture = total_child_preparation_fixture();
            let material = prepare_total_child(&mut fixture);
            let response = total_child_success_response(&fixture, &material);
            let authority = total_child_observation_authority(
                &fixture,
                material.prepared_event.id,
                ChildRepositoryExplorerObservedEvidence::Response(response.clone()),
            );
            let terminal = fixture
                .store
                .observe_child_repository_explorer_turn(fixture.run.id, authority)
                .expect("exact adapter response terminalizes through Store");
            assert!(matches!(
                terminal.append,
                IdempotentAppendOutcome::Appended { .. }
            ));
            let EventPayload::ChildModelInferenceObserved(observed) = &terminal.event.payload
            else {
                panic!("Store must append a typed child model observation")
            };
            assert_eq!(
                terminal.event.causal_parent,
                Some(material.prepared_event.id)
            );
            assert_eq!(terminal.event.actor_id, fixture.spec.child_event_actor_id);
            assert_eq!(
                terminal.event.provenance.backend.as_ref(),
                Some(&fixture.spec.backend)
            );
            assert!(matches!(
                observed.outcome,
                ChildModelInferenceObservation::Succeeded { .. }
            ));
            let retained = read_canonical_json_artifact::<ChildModelEvidenceRecord>(
                &fixture.store.artifact_root,
                &observed.normalized_complete_evidence_artifact,
                CHILD_MODEL_EVIDENCE_MEDIA_TYPE,
            )
            .expect("exact success evidence remains readable");
            let ChildModelCompleteEvidence::Succeeded {
                normalized_response,
                provider_evidence,
                ..
            } = retained.outcome
            else {
                panic!("exact response must remain successful")
            };
            assert_eq!(
                *normalized_response,
                serde_json::from_value(response.value.clone()).expect("typed response decodes")
            );
            assert_eq!(
                provider_evidence,
                serde_json::to_value(&response).expect("adapter response serializes")
            );
            assert!(
                fixture
                    .store
                    .recover_child_repository_explorer_turn(
                        fixture.run.id,
                        fixture.spec.work_order_id,
                    )
                    .expect("terminal history replays")
                    .is_none(),
                "an Observed Prepared boundary must never be exposed for redispatch"
            );
        }

