        #[test]
        fn v2_child_authority_binds_exact_typed_planner_work_order_semantics() {
            let case = build_case();
            let planned = birdcode_prompting::PlannerReplannerV2PlannedWorkOrder {
                id: case.issued.spec.planner_work_order_local_id.clone(),
                revision: 1,
                objective: case.issued.spec.objective.clone(),
                obligations: BTreeSet::new(),
                dependencies: BTreeSet::new(),
                verification_targets: BTreeSet::new(),
                required_access: birdcode_prompting::PlannerReplannerAccess::ReadOnly,
                state: birdcode_prompting::PlannerReplannerV2PlannedWorkOrderState::Pending,
                basis: birdcode_prompting::PlannerReplannerDecisionBasis {
                    evidence_ids: BTreeSet::new(),
                    rationale: "typed fixture basis".to_owned(),
                },
            };
            let binding_for = |planned: &birdcode_prompting::PlannerReplannerV2PlannedWorkOrder| {
                let artifact = put_json(&case.store, planned, PLANNER_WORK_ORDER_V2_MEDIA_TYPE);
                birdcode_protocol::PlannerDelegatedWorkOrderBindingV1 {
                    work_order_id: planned.id.clone(),
                    revision: planned.revision,
                    work_order_digest: digest_ref(&artifact),
                    work_order_artifact: artifact,
                }
            };
            validate_child_planned_work_order_authority(
                &case.store.artifact_root,
                &binding_for(&planned),
                &case.issued.spec,
            )
            .expect("exact pending read-only dependency-free planner work order validates");

            let mut mutations = Vec::new();
            let mut objective = planned.clone();
            objective.objective = "semantically substituted task".to_owned();
            mutations.push(objective);
            let mut access = planned.clone();
            access.required_access = birdcode_prompting::PlannerReplannerAccess::WorkspaceWrite;
            mutations.push(access);
            let mut state = planned.clone();
            state.state = birdcode_prompting::PlannerReplannerV2PlannedWorkOrderState::Running;
            mutations.push(state);
            let mut dependency = planned;
            dependency
                .dependencies
                .insert("blocked-predecessor".to_owned());
            mutations.push(dependency);
            for mutation in mutations {
                assert!(matches!(
                    validate_child_planned_work_order_authority(
                        &case.store.artifact_root,
                        &binding_for(&mutation),
                        &case.issued.spec,
                    ),
                    Err(StoreError::InvalidStateEvent)
                ));
            }
        }

        #[derive(Clone, Copy)]
        enum ChildModelTerminalFixture {
            Observed,
            Unknown,
        }

        #[allow(
            clippy::too_many_lines,
            reason = "the fixture retains both exact Observed and Unknown terminal documents"
        )]
        fn try_append_child_model_terminal(
            fixture: &mut TotalChildPreparationFixture,
            prepared_event: &EventEnvelope,
            causal_parent: EventId,
            terminal: ChildModelTerminalFixture,
        ) -> Result<EventEnvelope, StoreError> {
            let EventPayload::ChildModelInferencePreparedV2(prepared_v2) = &prepared_event.payload
            else {
                panic!("fixture preparation is v2")
            };
            let prepared = &prepared_v2.prepared;
            let finished_at = test_clock(fixture.runtime_instance_id, 30);
            let (artifact, payload) = match terminal {
                ChildModelTerminalFixture::Observed => {
                    let error = birdcode_protocol::ChildModelInferenceError {
                        kind: birdcode_protocol::ChildModelInferenceErrorKind::Timeout,
                        retry: RetryDisposition::RequiresNewAttempt,
                        cancellation: None,
                    };
                    let record = ChildModelEvidenceRecord {
                        contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                        binding: fixture.binding.clone(),
                        model_call_id: prepared.model_call_id,
                        model_call_ordinal: prepared.model_call_ordinal,
                        prepared_event_id: prepared_event.id,
                        backend_model: prepared.backend_model.clone(),
                        backend_instance: prepared.backend_instance.clone(),
                        model_lineage: prepared.model_lineage.clone(),
                        prompt_manifest_digest: prepared.prompt_manifest_digest.clone(),
                        prompt_digest: prepared.prompt_digest.clone(),
                        request_digest: prepared.request_digest.clone(),
                        token_reservation_id: prepared.token_reservation.id,
                        prepared_at: prepared.prepared_at.clone(),
                        finished_at: finished_at.clone(),
                        outcome: ChildModelCompleteEvidence::Failed {
                            error: error.clone(),
                            normalized_error: serde_json::json!({"kind": "timeout"}),
                        },
                    };
                    let artifact =
                        put_json(&fixture.store, &record, CHILD_MODEL_EVIDENCE_MEDIA_TYPE);
                    let payload = EventPayload::ChildModelInferenceObserved(
                        birdcode_protocol::ChildModelInferenceObserved {
                            binding: fixture.binding.clone(),
                            model_call_id: prepared.model_call_id,
                            model_call_ordinal: prepared.model_call_ordinal,
                            prepared_event_id: prepared_event.id,
                            backend_model: prepared.backend_model.clone(),
                            backend_instance: prepared.backend_instance.clone(),
                            model_lineage: prepared.model_lineage.clone(),
                            token_reservation_id: prepared.token_reservation.id,
                            normalized_complete_evidence_artifact: artifact.clone(),
                            evidence_digest: digest_ref(&artifact),
                            finished_at,
                            outcome: ChildModelInferenceObservation::Failed { error },
                        },
                    );
                    (artifact, payload)
                }
                ChildModelTerminalFixture::Unknown => {
                    let reason =
                        birdcode_protocol::UnknownInferenceOutcomeReason::RuntimeRestartedBeforeObservation;
                    let boundary = UnknownInferenceBoundary::Restart;
                    let record = ChildModelUnknownRecord {
                        contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                        binding: fixture.binding.clone(),
                        model_call_id: prepared.model_call_id,
                        model_call_ordinal: prepared.model_call_ordinal,
                        prepared_event_id: prepared_event.id,
                        backend_model: prepared.backend_model.clone(),
                        backend_instance: prepared.backend_instance.clone(),
                        model_lineage: prepared.model_lineage.clone(),
                        prompt_manifest_digest: prepared.prompt_manifest_digest.clone(),
                        prompt_digest: prepared.prompt_digest.clone(),
                        request_digest: prepared.request_digest.clone(),
                        token_reservation_id: prepared.token_reservation.id,
                        prepared_at: prepared.prepared_at.clone(),
                        boundary_at: finished_at.clone(),
                        reason,
                        boundary,
                        cancellation: None,
                        retry: RetryDisposition::RequiresNewAttempt,
                    };
                    let artifact =
                        put_json(&fixture.store, &record, CHILD_MODEL_UNKNOWN_MEDIA_TYPE);
                    let payload = EventPayload::ChildModelInferenceOutcomeUnknown(
                        ChildModelInferenceOutcomeUnknown {
                            binding: fixture.binding.clone(),
                            model_call_id: prepared.model_call_id,
                            model_call_ordinal: prepared.model_call_ordinal,
                            prepared_event_id: prepared_event.id,
                            backend_model: prepared.backend_model.clone(),
                            backend_instance: prepared.backend_instance.clone(),
                            model_lineage: prepared.model_lineage.clone(),
                            token_reservation_id: prepared.token_reservation.id,
                            boundary_artifact: artifact.clone(),
                            boundary_digest: digest_ref(&artifact),
                            boundary_at: finished_at,
                            reason,
                            boundary,
                            cancellation: None,
                            retry: RetryDisposition::RequiresNewAttempt,
                        },
                    );
                    (artifact, payload)
                }
            };
            fixture.store.append_event(NewEvent {
                session_id: prepared_event.session_id,
                run_id: prepared_event.run_id,
                actor_id: fixture.spec.child_event_actor_id,
                causal_parent: Some(causal_parent),
                provenance: Provenance {
                    producer: "fixture-child-terminal".to_owned(),
                    backend: Some(fixture.spec.backend.clone()),
                    raw_artifact: Some(artifact),
                },
                payload,
            })
        }

        fn append_child_model_terminal(
            fixture: &mut TotalChildPreparationFixture,
            prepared_event: &EventEnvelope,
            causal_parent: EventId,
            terminal: ChildModelTerminalFixture,
        ) {
            try_append_child_model_terminal(fixture, prepared_event, causal_parent, terminal)
                .expect("exact child model terminal commits");
        }

