        #[test]
        fn pending_child_model_can_adopt_same_runtime_claim_renewal_and_terminalize_once() {
            let mut fixture = total_child_preparation_fixture();
            let material = fixture
                .store
                .prepare_child_repository_explorer_turn(
                    fixture.run.id,
                    fixture.spec.work_order_id,
                    fixture.authority.clone(),
                )
                .expect("child Prepared commits before provider I/O")
                .material;
            let prepared = material.prepared_event.clone();
            let before = fixture
                .store
                .child_work_order_projection(fixture.run.id, fixture.spec.work_order_id)
                .expect("child projection remains readable")
                .expect("issued child exists");
            let prior_claim = before.active_claim.claim.clone();
            let prior_claim_event = before.active_claim.event.clone();
            let renewed_claim_id = birdcode_protocol::RunClaimId::new();
            let renewed_claim = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.run.spec.session_id,
                    run_id: Some(fixture.run.id),
                    actor_id: prior_claim_event.actor_id,
                    causal_parent: Some(prepared.id),
                    provenance: provenance(),
                    payload: EventPayload::RunClaimed(birdcode_protocol::RunClaimed {
                        claim_id: renewed_claim_id,
                        runtime_instance_id: fixture.runtime_instance_id,
                        claim_generation: prior_claim.claim_generation + 1,
                        cancellation_generation: prior_claim.cancellation_generation,
                        lease_expires_at: Utc::now() + chrono::Duration::minutes(10),
                    }),
                })
                .expect("same runtime renews the run claim during a pending model effect");
            let adoption = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.run.spec.session_id,
                    run_id: Some(fixture.run.id),
                    actor_id: prior_claim_event.actor_id,
                    causal_parent: Some(prepared.id),
                    provenance: Provenance {
                        producer: "fixture-child-claim-adoption".to_owned(),
                        backend: None,
                        raw_artifact: None,
                    },
                    payload: EventPayload::ChildExecutionClaimAdopted(
                        birdcode_protocol::ChildExecutionClaimAdoptedV1 {
                            adoption_id: birdcode_protocol::ChildClaimAdoptionId::new(),
                            work_order_id: fixture.spec.work_order_id,
                            execution_id: fixture.spec.execution_id,
                            attempt_id: Some(fixture.binding.attempt_id),
                            prior_claim_event_id: prior_claim_event.id,
                            prior_claim_id: prior_claim.claim_id,
                            prior_claim_generation: prior_claim.claim_generation,
                            prior_runtime_instance_id: prior_claim.runtime_instance_id,
                            new_claim_event_id: renewed_claim.id,
                            new_claim_id: renewed_claim_id,
                            new_claim_generation: prior_claim.claim_generation + 1,
                            new_runtime_instance_id: fixture.runtime_instance_id,
                            cancellation_generation: prior_claim.cancellation_generation,
                            kind: ChildClaimAdoptionKindV1::Renewal,
                        },
                    ),
                })
                .expect("pending child capability adopts the exact renewed claim");

            let response = total_child_success_response(&fixture, &material);
            let authority = total_child_observation_authority(
                &fixture,
                prepared.id,
                ChildRepositoryExplorerObservedEvidence::Response(response),
            );
            let terminal = fixture
                .store
                .observe_child_repository_explorer_turn(fixture.run.id, authority)
                .expect("Store derives the post-adoption causal parent");
            assert_eq!(terminal.event.causal_parent, Some(adoption.id));
            let after = fixture
                .store
                .child_work_order_projection(fixture.run.id, fixture.spec.work_order_id)
                .expect("renewed child projection remains replayable")
                .expect("issued child exists");
            assert_eq!(after.active_claim.event.id, renewed_claim.id);
            assert_eq!(after.attempts[0].completed_model_calls, 1);
            assert!(matches!(after.recovery, ChildRecoveryState::ReadyForTool));
            assert!(
                fixture
                    .store
                    .recover_child_repository_explorer_turn(
                        fixture.run.id,
                        fixture.spec.work_order_id,
                    )
                    .expect("closed Prepared recovery remains valid")
                    .is_none(),
                "a terminalized Prepared must never be redispatched"
            );
        }

        #[allow(
            clippy::too_many_lines,
            reason = "the exact-expiry fixture proves Prepared can only close through typed Unknown"
        )]
        #[test]
        fn pending_child_model_claim_gap_rejects_observed_and_requires_unknown() {
            let mut fixture = total_child_preparation_fixture();
            let material = fixture
                .store
                .prepare_child_repository_explorer_turn(
                    fixture.run.id,
                    fixture.spec.work_order_id,
                    fixture.authority.clone(),
                )
                .expect("child Prepared commits")
                .material;
            let prepared = material.prepared_event.clone();
            let before = fixture
                .store
                .child_work_order_projection(fixture.run.id, fixture.spec.work_order_id)
                .expect("pending child replays")
                .expect("child exists");
            let prior_claim = before.active_claim.claim;
            let prior_claim_event = before.active_claim.event;
            let renewed_claim_id = RunClaimId::new();
            let transaction = fixture
                .store
                .connection
                .transaction_with_behavior(TransactionBehavior::Immediate)
                .expect("gap fixture transaction begins");
            let mut renewed_claim = preallocate_event_envelope(
                &transaction,
                NewEvent {
                    session_id: fixture.run.spec.session_id,
                    run_id: Some(fixture.run.id),
                    actor_id: prior_claim_event.actor_id,
                    causal_parent: Some(prepared.id),
                    provenance: provenance(),
                    payload: EventPayload::RunClaimed(RunClaimed {
                        claim_id: renewed_claim_id,
                        runtime_instance_id: fixture.runtime_instance_id,
                        claim_generation: prior_claim.claim_generation + 1,
                        cancellation_generation: prior_claim.cancellation_generation,
                        lease_expires_at: prior_claim.lease_expires_at
                            + chrono::Duration::minutes(10),
                    }),
                },
            )
            .expect("gap claim preallocates");
            renewed_claim.occurred_at = prior_claim.lease_expires_at - chrono::Duration::seconds(1);
            insert_event_in_transaction(&transaction, &renewed_claim)
                .expect("pre-expiry renewal fixture inserts");
            let mut adoption = preallocate_event_envelope(
                &transaction,
                NewEvent {
                    session_id: fixture.run.spec.session_id,
                    run_id: Some(fixture.run.id),
                    actor_id: prior_claim_event.actor_id,
                    causal_parent: Some(prepared.id),
                    provenance: Provenance {
                        producer: "fixture-child-claim-gap-adoption".to_owned(),
                        backend: None,
                        raw_artifact: None,
                    },
                    payload: EventPayload::ChildExecutionClaimAdopted(
                        birdcode_protocol::ChildExecutionClaimAdoptedV1 {
                            adoption_id: birdcode_protocol::ChildClaimAdoptionId::new(),
                            work_order_id: fixture.spec.work_order_id,
                            execution_id: fixture.spec.execution_id,
                            attempt_id: Some(fixture.binding.attempt_id),
                            prior_claim_event_id: prior_claim_event.id,
                            prior_claim_id: prior_claim.claim_id,
                            prior_claim_generation: prior_claim.claim_generation,
                            prior_runtime_instance_id: prior_claim.runtime_instance_id,
                            new_claim_event_id: renewed_claim.id,
                            new_claim_id: renewed_claim_id,
                            new_claim_generation: prior_claim.claim_generation + 1,
                            new_runtime_instance_id: fixture.runtime_instance_id,
                            cancellation_generation: prior_claim.cancellation_generation,
                            kind: ChildClaimAdoptionKindV1::Renewal,
                        },
                    ),
                },
            )
            .expect("boundary adoption preallocates");
            adoption.occurred_at = prior_claim.lease_expires_at;
            insert_event_in_transaction(&transaction, &adoption)
                .expect("exact-expiry adoption fixture inserts");
            transaction.commit().expect("boundary fixture commits");
            assert!(matches!(
                try_append_child_model_terminal(
                    &mut fixture,
                    &prepared,
                    adoption.id,
                    ChildModelTerminalFixture::Observed,
                ),
                Err(StoreError::InvalidStateEvent)
            ));
            try_append_child_model_terminal(
                &mut fixture,
                &prepared,
                adoption.id,
                ChildModelTerminalFixture::Unknown,
            )
            .expect("typed Unknown closes the indeterminate gap-crossing effect");
            let after = fixture
                .store
                .child_work_order_projection(fixture.run.id, fixture.spec.work_order_id)
                .expect("gap-reconciled child replays")
                .expect("child exists");
            assert!(!after.attempts[0].monotonic_clock_contiguous);
        }

