    #[test]
    fn completion_terminal_evidence_requires_one_exact_typed_packet_entry() {
        let binding = ChildExecutionBinding {
            work_order_id: ChildWorkOrderId::new(),
            execution_id: ChildExecutionId::new(),
            attempt_id: ChildAttemptId::new(),
            child_actor_id: birdcode_protocol::ChildActorId::new(),
            context_id: birdcode_protocol::ChildContextId::new(),
            work_order_digest: digest('a'),
            context_manifest_digest: digest('b'),
        };
        let finished_event_id = EventId::new();
        let runtime_instance_id = RuntimeInstanceId::new();
        let cause = ChildCancellationCauseV1 {
            request_event_id: EventId::new(),
            request_id: birdcode_protocol::CancellationRequestId::new(),
            cancellation_generation: 1,
        };
        let terminal = birdcode_protocol::ReconCompletionChildTerminalBindingV1 {
            binding: binding.clone(),
            started_event_id: EventId::new(),
            finished_event_id,
            started_at: RuntimeClockReading {
                runtime_instance_id,
                monotonic_nanos: 100,
                observed_at: Utc::now(),
            },
            finished_at: RuntimeClockReading {
                runtime_instance_id,
                monotonic_nanos: 200,
                observed_at: Utc::now(),
            },
            outcome: ChildExecutionOutcome::Cancelled { cause },
        };
        let exact = birdcode_protocol::PlannerEvidenceEntryV2 {
            evidence_id: birdcode_protocol::PlannerEvidenceEntryId::from_uuid(
                finished_event_id.as_uuid(),
            ),
            normalized_content_digest: digest('c'),
            material: birdcode_protocol::PlannerEvidenceMaterialV2::ChildCancelled(
                birdcode_protocol::PlannerChildCancelledEvidenceV2 {
                    binding,
                    finished_event_id,
                    cause,
                },
            ),
        };
        let mut packet = birdcode_protocol::PlannerEvidencePacketV2 {
            schema_version: birdcode_protocol::PLANNER_EVIDENCE_CONTRACT_VERSION,
            purpose: birdcode_protocol::PlannerTurnPurposeV1::EvidenceReplan,
            context_manifest_digest: digest('d'),
            entries: vec![exact.clone()],
        };
        assert!(recon_completion_packet_has_terminal(&packet, &terminal));

        packet.entries[0].material = birdcode_protocol::PlannerEvidenceMaterialV2::ChildCancelled(
            birdcode_protocol::PlannerChildCancelledEvidenceV2 {
                binding: terminal.binding.clone(),
                finished_event_id,
                cause: ChildCancellationCauseV1 {
                    cancellation_generation: 2,
                    ..cause
                },
            },
        );
        assert!(!recon_completion_packet_has_terminal(&packet, &terminal));

        packet.entries = vec![exact.clone(), exact];
        assert!(
            !recon_completion_packet_has_terminal(&packet, &terminal),
            "duplicate evidence identities must fail closed"
        );
    }

