        fn build_child_model_turn(
            fixture: &mut ChildStoreFixture,
            child: &IssuedChildFixture,
            runtime_instance_id: RuntimeInstanceId,
            monotonic_nanos: u64,
            model_call_ordinal: u32,
        ) -> (ChildModelInferencePrepared, ArtifactRef) {
            let prepared_at = clock(runtime_instance_id, monotonic_nanos);
            let model_call_id = ChildModelCallId::new();
            let token_reservation = TokenReservation {
                id: TokenReservationId::new(),
                reserved_tokens: 1024,
                max_output_tokens: 512,
            };
            let prompt = ChildModelPromptDocument {
                contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: child.binding.clone(),
                model_call_id,
                model_call_ordinal,
                prepared_at: prepared_at.clone(),
                prompt: serde_json::json!({
                    "objective": child.spec.objective,
                    "turn": model_call_ordinal,
                }),
            };
            let prompt_artifact =
                put_canonical(&fixture.store, &prompt, CHILD_MODEL_PROMPT_MEDIA_TYPE);
            let prompt_digest = artifact_digest(&prompt_artifact);
            let request = ChildModelRequestDocument {
                contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: child.binding.clone(),
                model_call_id,
                model_call_ordinal,
                backend_model: child.spec.resolved_model.clone(),
                model_lineage: child.spec.model_lineage.clone(),
                prompt_artifact: prompt_artifact.clone(),
                prompt_digest: prompt_digest.clone(),
                token_reservation: token_reservation.clone(),
                prepared_at: prepared_at.clone(),
                request: serde_json::json!({
                    "model": child.spec.resolved_model.model_id,
                    "response_contract": "repository_explorer_v1",
                }),
            };
            let request_artifact =
                put_canonical(&fixture.store, &request, CHILD_MODEL_REQUEST_MEDIA_TYPE);
            let request_digest = artifact_digest(&request_artifact);
            let manifest = ChildModelPromptManifest {
                contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: child.binding.clone(),
                model_call_id,
                model_call_ordinal,
                backend_model: child.spec.resolved_model.clone(),
                model_lineage: child.spec.model_lineage.clone(),
                prompt_artifact: prompt_artifact.clone(),
                prompt_digest: prompt_digest.clone(),
                request_artifact: request_artifact.clone(),
                request_digest: request_digest.clone(),
                token_reservation: token_reservation.clone(),
                prepared_at: prepared_at.clone(),
            };
            let prompt_manifest_artifact = put_canonical(
                &fixture.store,
                &manifest,
                CHILD_MODEL_PROMPT_MANIFEST_MEDIA_TYPE,
            );
            let payload = ChildModelInferencePrepared {
                binding: child.binding.clone(),
                model_call_id,
                model_call_ordinal,
                backend_model: child.spec.resolved_model.clone(),
                model_lineage: child.spec.model_lineage.clone(),
                prompt_manifest_digest: artifact_digest(&prompt_manifest_artifact),
                prompt_manifest_artifact: prompt_manifest_artifact.clone(),
                prompt_artifact,
                prompt_digest,
                request_artifact,
                request_digest,
                token_reservation,
                prepared_at,
            };
            (payload, prompt_manifest_artifact)
        }

        fn prepare_child_model_turn(
            fixture: &mut ChildStoreFixture,
            child: &IssuedChildFixture,
            parent: EventId,
            runtime_instance_id: RuntimeInstanceId,
            monotonic_nanos: u64,
            model_call_ordinal: u32,
        ) -> (EventEnvelope, ChildModelInferencePrepared) {
            let (payload, prompt_manifest_artifact) = build_child_model_turn(
                fixture,
                child,
                runtime_instance_id,
                monotonic_nanos,
                model_call_ordinal,
            );
            let event = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(fixture.run.id),
                    actor_id: child.spec.child_event_actor_id,
                    causal_parent: Some(parent),
                    provenance: child_backend_provenance(
                        &child.spec,
                        Some(prompt_manifest_artifact),
                    ),
                    payload: EventPayload::ChildModelInferencePrepared(payload.clone()),
                })
                .expect("valid child model preparation should persist");
            (event, payload)
        }

        fn observe_successful_child_model_turn(
            fixture: &mut ChildStoreFixture,
            child: &IssuedChildFixture,
            prepared_event: &EventEnvelope,
            prepared: &ChildModelInferencePrepared,
            runtime_instance_id: RuntimeInstanceId,
            monotonic_nanos: u64,
        ) -> EventEnvelope {
            let finished_at = clock(runtime_instance_id, monotonic_nanos);
            let token_usage = TokenUsage {
                input_tokens: 10,
                output_tokens: 5,
                total_tokens: 15,
                cached_input_tokens: Some(0),
            };
            let complete_outcome = ChildModelCompleteEvidence::Succeeded {
                reported_backend_model: child.spec.resolved_model.clone(),
                token_usage: token_usage.clone(),
                normalized_response: serde_json::json!({
                    "repository_explorer_output": {
                        "turn": prepared.model_call_ordinal,
                    },
                }),
            };
            let evidence = ChildModelEvidenceRecord {
                contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: child.binding.clone(),
                model_call_id: prepared.model_call_id,
                model_call_ordinal: prepared.model_call_ordinal,
                prepared_event_id: prepared_event.id,
                backend_model: child.spec.resolved_model.clone(),
                model_lineage: child.spec.model_lineage.clone(),
                prompt_manifest_digest: prepared.prompt_manifest_digest.clone(),
                prompt_digest: prepared.prompt_digest.clone(),
                request_digest: prepared.request_digest.clone(),
                token_reservation_id: prepared.token_reservation.id,
                prepared_at: prepared.prepared_at.clone(),
                finished_at: finished_at.clone(),
                outcome: complete_outcome,
            };
            let evidence_artifact =
                put_canonical(&fixture.store, &evidence, CHILD_MODEL_EVIDENCE_MEDIA_TYPE);
            fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(fixture.run.id),
                    actor_id: child.spec.child_event_actor_id,
                    causal_parent: Some(prepared_event.id),
                    provenance: child_backend_provenance(
                        &child.spec,
                        Some(evidence_artifact.clone()),
                    ),
                    payload: EventPayload::ChildModelInferenceObserved(
                        birdcode_protocol::ChildModelInferenceObserved {
                            binding: child.binding.clone(),
                            model_call_id: prepared.model_call_id,
                            model_call_ordinal: prepared.model_call_ordinal,
                            prepared_event_id: prepared_event.id,
                            backend_model: child.spec.resolved_model.clone(),
                            model_lineage: child.spec.model_lineage.clone(),
                            token_reservation_id: prepared.token_reservation.id,
                            evidence_digest: artifact_digest(&evidence_artifact),
                            normalized_complete_evidence_artifact: evidence_artifact,
                            finished_at,
                            outcome: ChildModelInferenceObservation::Succeeded {
                                reported_backend_model: child.spec.resolved_model.clone(),
                                token_usage,
                            },
                        },
                    ),
                })
                .expect("valid child model observation should persist")
        }

        fn complete_successful_child_model_turn(
            fixture: &mut ChildStoreFixture,
            child: &IssuedChildFixture,
            parent: EventId,
            runtime_instance_id: RuntimeInstanceId,
            prepared_nanos: u64,
            finished_nanos: u64,
            model_call_ordinal: u32,
        ) -> EventEnvelope {
            let (prepared_event, prepared) = prepare_child_model_turn(
                fixture,
                child,
                parent,
                runtime_instance_id,
                prepared_nanos,
                model_call_ordinal,
            );
            observe_successful_child_model_turn(
                fixture,
                child,
                &prepared_event,
                &prepared,
                runtime_instance_id,
                finished_nanos,
            )
        }

        fn finish_child_without_handoff(
            fixture: &mut ChildStoreFixture,
            child: &IssuedChildFixture,
            parent: EventId,
            runtime_instance_id: RuntimeInstanceId,
            monotonic_nanos: u64,
        ) -> EventEnvelope {
            fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(fixture.run.id),
                    actor_id: child.spec.child_event_actor_id,
                    causal_parent: Some(parent),
                    provenance: child_backend_provenance(&child.spec, None),
                    payload: EventPayload::ChildExecutionFinished(
                        birdcode_protocol::ChildExecutionFinished {
                            binding: child.binding.clone(),
                            handoff_event_id: None,
                            completed_model_calls: 0,
                            completed_tool_calls: 0,
                            finished_at: clock(runtime_instance_id, monotonic_nanos),
                            outcome: ChildExecutionOutcome::Failed {
                                kind: birdcode_protocol::ChildExecutionFailureKind::Model,
                                retry: RetryDisposition::Never,
                            },
                        },
                    ),
                })
                .expect("valid failed child terminal should persist")
        }

        #[test]
        #[allow(
            clippy::too_many_lines,
            reason = "the end-to-end adversarial fixture keeps every retained child artifact explicit"
        )]
        fn child_reconnaissance_replays_exact_tool_evidence_and_structured_handoff() {
            let mut fixture = child_store_fixture(2);
            let child = issue_child(&mut fixture, "Inspect src/lib.rs without modifying it");
            let runtime_instance_id = RuntimeInstanceId::new();
            let started = start_child(&mut fixture, &child, runtime_instance_id, 100);
            let initial_model = complete_successful_child_model_turn(
                &mut fixture,
                &child,
                started.id,
                runtime_instance_id,
                105,
                110,
                1,
            );
            let operation = birdcode_protocol::ChildToolOperation::RepositoryTree {
                root: PathBuf::from("src").into(),
                max_depth: 4,
                max_entries: 1024,
            };
            let tool_call_id = birdcode_protocol::ChildToolCallId::new();
            let prepared_at = clock(runtime_instance_id, 120);
            let request = birdcode_protocol::ChildToolRequestRecord {
                contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: child.binding.clone(),
                tool_call_id,
                tool_ordinal: 1,
                operation: operation.clone(),
                prepared_at: prepared_at.clone(),
            };
            let request_artifact =
                put_canonical(&fixture.store, &request, CHILD_TOOL_REQUEST_MEDIA_TYPE);
            let prepared = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(fixture.run.id),
                    actor_id: child.spec.child_event_actor_id,
                    causal_parent: Some(initial_model.id),
                    provenance: child_backend_provenance(
                        &child.spec,
                        Some(request_artifact.clone()),
                    ),
                    payload: EventPayload::ChildToolPrepared(
                        birdcode_protocol::ChildToolPrepared {
                            binding: child.binding.clone(),
                            tool_call_id,
                            tool_ordinal: 1,
                            operation: operation.clone(),
                            request_digest: artifact_digest(&request_artifact),
                            request_artifact,
                            prepared_at: prepared_at.clone(),
                        },
                    ),
                })
                .expect("prepared child tool should persist");
            let result_artifact = fixture
                .store
                .put_artifact(b"{\"entries\":[\"src/lib.rs\"]}", "application/json")
                .expect("tool result should persist");
            let outcome = ChildToolObservation::Succeeded {
                result: ChildToolSuccess::TreeEnumerated {
                    result_artifact: result_artifact.clone(),
                    entries_returned: 1,
                    entries_scanned: 1,
                    truncated: false,
                },
            };
            let finished_at = clock(runtime_instance_id, 170);
            let evidence = ChildToolEvidenceRecord {
                contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: child.binding.clone(),
                tool_call_id,
                prepared_event_id: prepared.id,
                operation,
                prepared_at,
                finished_at: finished_at.clone(),
                outcome: outcome.clone(),
            };
            let evidence_artifact =
                put_canonical(&fixture.store, &evidence, CHILD_TOOL_EVIDENCE_MEDIA_TYPE);
            let observed = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(fixture.run.id),
                    actor_id: child.spec.child_event_actor_id,
                    causal_parent: Some(prepared.id),
                    provenance: child_backend_provenance(
                        &child.spec,
                        Some(evidence_artifact.clone()),
                    ),
                    payload: EventPayload::ChildToolObserved(
                        birdcode_protocol::ChildToolObserved {
                            binding: child.binding.clone(),
                            tool_call_id,
                            prepared_event_id: prepared.id,
                            evidence_digest: artifact_digest(&evidence_artifact),
                            normalized_complete_evidence_artifact: evidence_artifact,
                            finished_at,
                            outcome,
                        },
                    ),
                })
                .expect("observed child tool should persist");
            let final_model = complete_successful_child_model_turn(
                &mut fixture,
                &child,
                observed.id,
                runtime_instance_id,
                175,
                180,
                2,
            );
            let forged_handoff_id = birdcode_protocol::ChildHandoffId::new();
            let forged_handoff_document = ChildHandoffDocument {
                contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: child.binding.clone(),
                handoff_id: forged_handoff_id,
                findings: vec![birdcode_protocol::ChildHandoffFinding {
                    finding_id: "forged-finding".to_owned(),
                    statement: "This evidence points at an unrelated event".to_owned(),
                    confidence: birdcode_protocol::ChildFindingConfidence::High,
                    evidence: vec![birdcode_protocol::ChildHandoffEvidenceBinding {
                        tool_call_id,
                        observed_event_id: EventId::new(),
                        result_artifact: result_artifact.clone(),
                    }],
                }],
                unresolved_questions: Vec::new(),
            };
            let forged_handoff_artifact = put_canonical(
                &fixture.store,
                &forged_handoff_document,
                CHILD_HANDOFF_MEDIA_TYPE,
            );
            let forged_error = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(fixture.run.id),
                    actor_id: child.spec.child_event_actor_id,
                    causal_parent: Some(final_model.id),
                    provenance: child_backend_provenance(
                        &child.spec,
                        Some(forged_handoff_artifact.clone()),
                    ),
                    payload: EventPayload::ChildHandoffCommitted(
                        birdcode_protocol::ChildHandoffCommitted {
                            binding: child.binding.clone(),
                            handoff_id: forged_handoff_id,
                            handoff_digest: artifact_digest(&forged_handoff_artifact),
                            handoff_artifact: forged_handoff_artifact,
                        },
                    ),
                })
                .expect_err("handoff evidence must name the exact observed event");
            assert!(matches!(forged_error, StoreError::InvalidStateEvent));
            let handoff_id = birdcode_protocol::ChildHandoffId::new();
            let handoff_document = ChildHandoffDocument {
                contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: child.binding.clone(),
                handoff_id,
                findings: vec![birdcode_protocol::ChildHandoffFinding {
                    finding_id: "finding-1".to_owned(),
                    statement: "The bounded tree contains src/lib.rs".to_owned(),
                    confidence: birdcode_protocol::ChildFindingConfidence::High,
                    evidence: vec![birdcode_protocol::ChildHandoffEvidenceBinding {
                        tool_call_id,
                        observed_event_id: observed.id,
                        result_artifact: result_artifact.clone(),
                    }],
                }],
                unresolved_questions: vec![birdcode_protocol::ChildUnresolvedQuestion {
                    question_id: "question-1".to_owned(),
                    question: "Should another file be inspected?".to_owned(),
                }],
            };
            let handoff_artifact =
                put_canonical(&fixture.store, &handoff_document, CHILD_HANDOFF_MEDIA_TYPE);
            let handoff = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(fixture.run.id),
                    actor_id: child.spec.child_event_actor_id,
                    causal_parent: Some(final_model.id),
                    provenance: child_backend_provenance(
                        &child.spec,
                        Some(handoff_artifact.clone()),
                    ),
                    payload: EventPayload::ChildHandoffCommitted(
                        birdcode_protocol::ChildHandoffCommitted {
                            binding: child.binding.clone(),
                            handoff_id,
                            handoff_digest: artifact_digest(&handoff_artifact),
                            handoff_artifact,
                        },
                    ),
                })
                .expect("evidence-bound handoff should persist");
            let terminal = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(fixture.run.id),
                    actor_id: child.spec.child_event_actor_id,
                    causal_parent: Some(handoff.id),
                    provenance: child_backend_provenance(&child.spec, None),
                    payload: EventPayload::ChildExecutionFinished(
                        birdcode_protocol::ChildExecutionFinished {
                            binding: child.binding.clone(),
                            handoff_event_id: Some(handoff.id),
                            completed_model_calls: 2,
                            completed_tool_calls: 1,
                            finished_at: clock(runtime_instance_id, 200),
                            outcome: ChildExecutionOutcome::Succeeded,
                        },
                    ),
                })
                .expect("successful child terminal should persist");

            let projection = fixture
                .store
                .child_work_order_projection(fixture.run.id, child.spec.work_order_id)
                .expect("child history should replay")
                .expect("child work order should exist");
            assert_eq!(projection.state, ChildWorkOrderState::Succeeded);
            assert_eq!(projection.attempts.len(), 1);
            assert_eq!(projection.attempts[0].completed_model_calls, 2);
            assert_eq!(projection.attempts[0].completed_tool_calls, 1);
            assert_eq!(projection.attempts[0].handoff_event_id, Some(handoff.id));
            assert_eq!(projection.attempts[0].terminal_event_id, Some(terminal.id));
        }

        #[test]
        #[allow(
            clippy::too_many_lines,
            reason = "the substitution regression retains both forged artifact and causal attempts"
        )]
        fn child_tool_request_and_causal_substitution_fail_without_partial_history() {
            let mut fixture = child_store_fixture(1);
            let child = issue_child(&mut fixture, "Inspect one exact path");
            let runtime_instance_id = RuntimeInstanceId::new();
            let started = start_child(&mut fixture, &child, runtime_instance_id, 10);
            let model = complete_successful_child_model_turn(
                &mut fixture,
                &child,
                started.id,
                runtime_instance_id,
                12,
                15,
                1,
            );
            let retained_operation = birdcode_protocol::ChildToolOperation::LiteralSearch {
                root: PathBuf::from(".").into(),
                literal_utf8: "exact literal 世界".to_owned(),
                max_depth: 4,
                max_files: 32,
                max_matches: 4,
                max_bytes_per_file: 512,
                max_total_bytes: 4096,
            };
            let substituted_operation = birdcode_protocol::ChildToolOperation::LiteralSearch {
                root: PathBuf::from(".").into(),
                literal_utf8: "different literal".to_owned(),
                max_depth: 4,
                max_files: 32,
                max_matches: 4,
                max_bytes_per_file: 512,
                max_total_bytes: 4096,
            };
            let tool_call_id = birdcode_protocol::ChildToolCallId::new();
            let prepared_at = clock(runtime_instance_id, 20);
            let retained = birdcode_protocol::ChildToolRequestRecord {
                contract_version: CHILD_RECONNAISSANCE_CONTRACT_VERSION,
                binding: child.binding.clone(),
                tool_call_id,
                tool_ordinal: 1,
                operation: retained_operation,
                prepared_at: prepared_at.clone(),
            };
            let request_artifact =
                put_canonical(&fixture.store, &retained, CHILD_TOOL_REQUEST_MEDIA_TYPE);
            let before = fixture
                .store
                .events_for_run_after(fixture.run.id, 0)
                .expect("history should load")
                .events
                .len();
            let error = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(fixture.run.id),
                    actor_id: child.spec.child_event_actor_id,
                    causal_parent: Some(model.id),
                    provenance: child_backend_provenance(
                        &child.spec,
                        Some(request_artifact.clone()),
                    ),
                    payload: EventPayload::ChildToolPrepared(
                        birdcode_protocol::ChildToolPrepared {
                            binding: child.binding.clone(),
                            tool_call_id,
                            tool_ordinal: 1,
                            operation: substituted_operation,
                            request_digest: artifact_digest(&request_artifact),
                            request_artifact: request_artifact.clone(),
                            prepared_at: prepared_at.clone(),
                        },
                    ),
                })
                .expect_err("substituted operation must not match retained request bytes");
            assert!(matches!(error, StoreError::InvalidStateEvent));
            let causal_error = fixture
                .store
                .append_event(NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(fixture.run.id),
                    actor_id: child.spec.child_event_actor_id,
                    causal_parent: Some(child.work_order_event.id),
                    provenance: child_backend_provenance(
                        &child.spec,
                        Some(request_artifact.clone()),
                    ),
                    payload: EventPayload::ChildToolPrepared(
                        birdcode_protocol::ChildToolPrepared {
                            binding: child.binding.clone(),
                            tool_call_id,
                            tool_ordinal: 1,
                            operation: retained.operation.clone(),
                            request_digest: artifact_digest(&request_artifact),
                            request_artifact,
                            prepared_at,
                        },
                    ),
                })
                .expect_err("tool preparation must descend from the active attempt tail");
            assert!(matches!(causal_error, StoreError::InvalidStateEvent));
            let after = fixture
                .store
                .events_for_run_after(fixture.run.id, 0)
                .expect("history should remain readable")
                .events
                .len();
            assert_eq!(after, before);

            let projection = fixture
                .store
                .child_work_order_projection(fixture.run.id, child.spec.work_order_id)
                .unwrap()
                .unwrap();
            assert_eq!(projection.state, ChildWorkOrderState::Running);
            assert_eq!(projection.attempts[0].completed_tool_calls, 0);
        }

