    #[test]
    fn idempotent_planner_observed_rejects_regressive_terminal_clock() {
        let mut fixture = default_exact_pair_fixture();
        let (prepared_event, prepared) = fresh_fixture_planner_prepared(&mut fixture);
        let actor_id = fixture.actor_id;
        let runtime_instance_id = fixture.runtime_instance_id;
        let renewed_at = Utc::now();
        let renewed = append_fixture_claim_at(
            &mut fixture,
            actor_id,
            runtime_instance_id,
            renewed_at,
            renewed_at + chrono::Duration::minutes(20),
        );
        let valid_clock = RuntimeClockReading {
            runtime_instance_id,
            monotonic_nanos: 110,
            observed_at: renewed.occurred_at + chrono::Duration::milliseconds(1),
        };
        let (observed_event, retained) = apply_fixture_planner_observed_at(
            &mut fixture,
            &prepared_event,
            &prepared,
            valid_clock.clone(),
            renewed.occurred_at + chrono::Duration::milliseconds(2),
        )
        .expect("baseline observation persists");
        let mut forged = observed_event.clone();
        let EventPayload::PlannerTurnObservedV1(observed) = &mut forged.payload else {
            panic!("observed terminal is typed")
        };
        observed.observed_at.monotonic_nanos = prepared.prepared_at.monotonic_nanos - 1;
        let authority = PlannerV2ObservationAuthority {
            event_id: forged.id,
            prepared_event_id: prepared_event.id,
            evidence: PlannerV2ObservedEvidence::NotDispatched {
                reason: PlannerV2NotDispatchedReason::ClaimLost,
            },
            observed_at: observed.observed_at.clone(),
        };
        assert!(
            validate_existing_planner_v2_observation(
                &fixture.store.connection,
                &fixture.store.artifact_root,
                fixture.run.id,
                &authority,
                &retained,
                &forged,
            )
            .is_err()
        );
    }

