    #[test]
    fn completion_snapshot_boundary_is_bounded_at_256_post_release_claims() {
        let mut fixture = default_exact_pair_fixture();
        let actor_id = fixture.actor_id;
        let runtime_instance_id = fixture.runtime_instance_id;
        let release = snapshot_release_event(
            &mut fixture,
            RuntimeClockReading {
                runtime_instance_id,
                monotonic_nanos: 100,
                observed_at: Utc::now(),
            },
        );
        let release = fixture
            .store
            .append_event(release)
            .expect("normal release persists");
        let base = release.occurred_at + chrono::Duration::seconds(1);
        let lease_expires_at = base + chrono::Duration::minutes(20);
        let mut latest = release;
        for ordinal in 1..=PARALLEL_RECON_COMPLETION_POST_RELEASE_MAX_CLAIM_TRANSITIONS {
            latest = append_fixture_claim_at(
                &mut fixture,
                actor_id,
                runtime_instance_id,
                base + chrono::Duration::milliseconds(
                    i64::try_from(ordinal).expect("bounded ordinal fits"),
                ),
                lease_expires_at,
            );
        }
        recon_completion_snapshot_boundary(
            &fixture.store.connection,
            &fixture.store.artifact_root,
            &fixture.run,
            fixture.lease_event.id,
            latest.id,
        )
        .expect("the exact 256-claim transition bound remains admissible");

        let overflow = append_fixture_claim_at(
            &mut fixture,
            actor_id,
            runtime_instance_id,
            base + chrono::Duration::milliseconds(257),
            lease_expires_at,
        );
        assert!(matches!(
            recon_completion_snapshot_boundary(
                &fixture.store.connection,
                &fixture.store.artifact_root,
                &fixture.run,
                fixture.lease_event.id,
                overflow.id,
            ),
            Err(StoreError::InvalidStateEvent)
        ));
    }

