    #[test]
    fn parallel_recon_exact_pair_issuance_retry_is_idempotent_after_claim_renewal() {
        let mut fixture = default_exact_pair_fixture();
        let first = fixture
            .store
            .issue_parallel_recon_exact_pair(fixture.run.id, fixture.authority.clone())
            .expect("first append succeeds");
        assert!(matches!(
            first,
            ParallelReconExactPairIssuanceOutcome::Appended { .. }
        ));
        let now = Utc::now();
        let renewed = fixture
            .store
            .refresh_parallel_recon_claim(
                fixture.run.id,
                ParallelReconClaimRefreshAuthority {
                    actor_id: fixture.actor_id,
                    runtime_instance_id: fixture.runtime_instance_id,
                    renewal_claim_id: RunClaimId::new(),
                    snapshot_capture_adoption_id: RepositorySnapshotCaptureClaimAdoptionId::new(),
                    child_adoption_ids: [
                        birdcode_protocol::ChildClaimAdoptionId::new(),
                        birdcode_protocol::ChildClaimAdoptionId::new(),
                    ],
                    refreshed_at: RuntimeClockReading {
                        runtime_instance_id: fixture.runtime_instance_id,
                        monotonic_nanos: 20,
                        observed_at: now,
                    },
                    fresh_through: now + chrono::Duration::minutes(31),
                    renewed_lease_expires_at: now + chrono::Duration::minutes(45),
                },
            )
            .expect("claim and both children renew atomically");
        assert!(matches!(
            renewed,
            ParallelReconClaimRefreshOutcome::Renewed { .. }
        ));
        let recovered = fixture
            .store
            .recover_parallel_recon_exact_pair(fixture.run.id, fixture.accepted_event.id)
            .expect("identity-free recovery survives renewal")
            .expect("the exact pair remains committed");
        assert!(
            recovered
                .children
                .iter()
                .all(|child| { child.projection.active_claim.claim.claim_generation == 2 })
        );
        let retry = fixture
            .store
            .issue_parallel_recon_exact_pair(fixture.run.id, fixture.authority.clone())
            .expect("historical exact bundle retries after renewal");
        let ParallelReconExactPairIssuanceOutcome::AlreadyPresent { children, .. } = retry else {
            panic!("retry must resolve the committed bundle")
        };
        assert_eq!(exact_pair_event_count(&fixture.store, fixture.run.id), 4);
        assert!(
            children
                .iter()
                .all(|child| { child.projection.active_claim.claim.claim_generation == 2 })
        );
    }

    #[test]
    fn parallel_recon_exact_pair_late_second_child_identity_collision_rolls_back_all_four() {
        let mut fixture = default_exact_pair_fixture();
        let transaction = fixture
            .store
            .connection
            .transaction_with_behavior(TransactionBehavior::Immediate)
            .expect("material transaction begins");
        let material = derive_parallel_recon_exact_pair_material(
            &transaction,
            &fixture.store.artifact_root,
            fixture.run.id,
            &fixture.authority,
            ParallelReconExactPairMaterialMode::Fresh,
        )
        .expect("fresh material derives");
        let EventPayload::ChildWorkOrderIssued(mut colliding_issuance) =
            material.children[1].issuance.event.payload.clone()
        else {
            panic!("derived second child retains issuance payload")
        };
        colliding_issuance.spec.repository_authority.tool_grants =
            parallel_recon_repository_grants([
                RepositoryToolGrantId::new(),
                RepositoryToolGrantId::new(),
                RepositoryToolGrantId::new(),
            ]);
        let colliding_payload = EventPayload::ChildWorkOrderIssued(colliding_issuance);
        transaction
            .rollback()
            .expect("material transaction rolls back");

        let other_run = Run::new(RunSpec {
            session_id: fixture.session.id,
            purpose: RunPurpose::Execute,
            plan_acceptance: PlanAcceptanceContract::NotApplicable,
            backend: fixture.run.spec.backend.clone(),
            input: Vec::new(),
            limits: RunLimits::default(),
        });
        let latest = latest_run_event(
            &fixture.store.connection,
            fixture.session.id,
            fixture.run.id,
        )
        .expect("latest event reads");
        fixture
            .store
            .create_run(
                &other_run,
                NewEvent {
                    session_id: fixture.session.id,
                    run_id: Some(other_run.id),
                    actor_id: fixture.actor_id,
                    causal_parent: Some(latest.id),
                    provenance: provenance(),
                    payload: EventPayload::RunCreated {
                        run: other_run.clone(),
                    },
                },
            )
            .expect("collision run persists");
        insert_exact_pair_fixture_event(
            &mut fixture.store,
            None,
            NewEvent {
                session_id: fixture.session.id,
                run_id: Some(other_run.id),
                actor_id: fixture.actor_id,
                causal_parent: None,
                provenance: provenance(),
                payload: colliding_payload,
            },
        );
        assert!(matches!(
            fixture
                .store
                .issue_parallel_recon_exact_pair(fixture.run.id, fixture.authority.clone()),
            Err(StoreError::InvalidStateEvent)
        ));
        assert_eq!(exact_pair_event_count(&fixture.store, fixture.run.id), 0);
        for event_id in parallel_recon_exact_pair_authority_event_ids(&fixture.authority) {
            assert!(
                load_event_by_id(&fixture.store.connection, event_id)
                    .expect("identity query succeeds")
                    .is_none()
            );
        }
    }

    #[test]
    fn parallel_recon_exact_pair_rejects_non_exact_or_unsafe_planner_work_orders() {
        let cases = vec![
            Vec::new(),
            vec![exact_pair_planned_work_order("one", "one")],
            vec![
                exact_pair_planned_work_order("one", "one"),
                exact_pair_planned_work_order("two", "two"),
                exact_pair_planned_work_order("three", "three"),
            ],
            vec![
                exact_pair_planned_work_order("same", "one"),
                exact_pair_planned_work_order("same", "two"),
            ],
            {
                let mut writable = exact_pair_planned_work_order("write", "write");
                writable.required_access =
                    birdcode_prompting::PlannerReplannerAccess::WorkspaceWrite;
                vec![writable, exact_pair_planned_work_order("read", "read")]
            },
            {
                let mut dependent = exact_pair_planned_work_order("dependent", "dependent");
                dependent.dependencies.insert("predecessor".to_owned());
                vec![dependent, exact_pair_planned_work_order("read", "read")]
            },
        ];
        for work_orders in cases {
            let mut fixture = exact_pair_fixture(work_orders);
            assert!(matches!(
                fixture
                    .store
                    .issue_parallel_recon_exact_pair(fixture.run.id, fixture.authority),
                Err(StoreError::InvalidStateEvent)
            ));
            assert_eq!(exact_pair_event_count(&fixture.store, fixture.run.id), 0);
        }
    }

